# QFC DeFi Operations Guide

## Overview

QFC supports standard EVM-compatible DeFi operations. All Solidity contracts deployed on Ethereum can run on QFC with minimal changes. Gas fees are extremely low (<$0.0001 per transaction).

## Staking

### Validator Staking

Validators secure the network through the Proof of Contribution (PoC) consensus.

| Parameter | Value |
|-----------|-------|
| Minimum stake | 10,000 QFC |
| Unstake delay | 7 days |
| Max active validators | 1,000 |
| Max single validator | 1% of total stake |
| Estimated APY | 8-18% |

```typescript
const staking = new QFCStaking('testnet');

// List validators
const validators = await staking.getValidators();

// Check stake for an address
const stake = await staking.getStake('0x1234...');

// Get contribution score (0-10000)
const score = await staking.getContributionScore('0x1234...');

// Detailed 7-dimension breakdown
const breakdown = await staking.getScoreBreakdown('0x1234...');
```

### Delegation

Delegate QFC to a validator without running a node.

| Parameter | Value |
|-----------|-------|
| Minimum delegation | 100 QFC |
| Commission range | 0-20% |
| Delegator reward | validator_share * (1 - commission) |

Delegates share in validator slashing risk.

## Token Swaps

QFC has a built-in SimpleSwap contract (constant product AMM, x*y=k).

```typescript
const contract = new QFCContract('testnet');

// Read pool reserves
const reserves = await contract.call(
  SWAP_ADDRESS,
  SWAP_ABI,
  'getReserves',
);

// Swap tokens (requires wallet)
await contract.send(
  SWAP_ADDRESS,
  SWAP_ABI,
  'swapExactTokensForTokens',
  [amountIn, amountOutMin, [tokenA, tokenB], deadline],
  wallet,
);
```

Swap fee: 0.3% per trade.

## Liquidity Provision

Provide liquidity to earn swap fees.

```typescript
// Add liquidity
await contract.send(
  SWAP_ADDRESS,
  SWAP_ABI,
  'addLiquidity',
  [tokenA, tokenB, amountA, amountB, minA, minB, deadline],
  wallet,
);

// Remove liquidity
await contract.send(
  SWAP_ADDRESS,
  SWAP_ABI,
  'removeLiquidity',
  [tokenA, tokenB, liquidity, minA, minB, deadline],
  wallet,
);
```

## Yield Vaults

QFC supports ERC-4626 style yield vaults.

```typescript
// Deposit into vault
await contract.send(VAULT_ADDRESS, VAULT_ABI, 'deposit', [amount, receiver], wallet);

// Check shares
const shares = await contract.call(VAULT_ADDRESS, VAULT_ABI, 'balanceOf', [address]);

// Withdraw
await contract.send(VAULT_ADDRESS, VAULT_ABI, 'withdraw', [amount, receiver, owner], wallet);
```

## Fee Structure

QFC uses EIP-1559 style dynamic gas pricing:

| Operation | Gas | Cost (1 Gwei base) |
|-----------|-----|---------------------|
| Simple transfer | 21,000 | 0.000021 QFC |
| ERC-20 transfer | ~65,000 | 0.000065 QFC |
| Swap | ~150,000 | 0.00015 QFC |
| Contract deploy | ~500,000 | 0.0005 QFC |
| NFT mint | ~100,000 | 0.0001 QFC |

Fee distribution: 50% block producer, 30% voters, 20% burned.

## Key Contract Addresses

Contract addresses are available via `qfc-contracts` repo. Use the QFC Explorer to verify addresses:
- Testnet: https://explorer.testnet.qfc.network/contracts
- Mainnet: https://explorer.qfc.network/contracts

#!/usr/bin/env node
/**
 * Demo: AI Oracle Agent
 *
 * Shows how an AI agent can answer on-chain queries:
 * 1. Register with InferenceSubmit + QueryOnly permissions
 * 2. Estimate fees before submitting
 * 3. Submit queries and decode results
 * 4. Monitor spending with preflight checks
 *
 * In production, a paymaster would sponsor gas so the agent
 * doesn't need to hold QFC directly (M2 feature).
 *
 * Usage:
 *   export OWNER_PRIVATE_KEY=0x...
 *   node scripts/demo-ai-oracle.mjs
 */

import { ethers } from 'ethers';
import { AgentWalletClient } from '../dist/agent-wallet.js';

const NETWORK = 'testnet';

async function main() {
  const ownerKey = process.env.OWNER_PRIVATE_KEY;
  if (!ownerKey) {
    console.error('Set OWNER_PRIVATE_KEY environment variable');
    process.exit(1);
  }

  const ownerWallet = new ethers.Wallet(ownerKey);
  const sessionWallet = ethers.Wallet.createRandom();

  console.log(`Owner: ${ownerWallet.address}`);
  console.log(`Oracle session key: ${sessionWallet.address}`);

  const client = new AgentWalletClient(NETWORK);

  // --- Register oracle agent ---

  console.log('\n[1/5] Registering oracle agent...');
  const reg = await client.register(ownerWallet, {
    agentId: 'oracle-1',
    agentAddress: sessionWallet.address,
    permissions: ['InferenceSubmit', 'QueryOnly'],
    dailyLimitQFC: '50',
    maxPerTxQFC: '5',
    depositQFC: '25',
  });
  console.log(`Registered: ${reg.explorerUrl}`);

  await client.issueSessionKey(ownerWallet, {
    agentId: 'oracle-1',
    sessionKeyAddress: sessionWallet.address,
    durationSeconds: 86400 * 3, // 3 days
  });
  console.log('Session key issued (3 day TTL)');

  // --- Oracle operates ---

  const oracle = new AgentWalletClient(NETWORK, {
    privateKey: sessionWallet.privateKey,
    agentId: 'oracle-1',
  });

  // Estimate fee first
  console.log('\n[2/5] Estimating fee...');
  const fee = await oracle.estimateFee('qfc-embed-small', 'TextEmbedding');
  console.log(`  Base fee: ${fee.baseFee} QFC`);
  console.log(`  GPU tier: ${fee.gpuTier}`);
  console.log(`  Est. time: ${fee.estimatedTimeMs}ms`);

  // Preflight check before spending
  console.log('\n[3/5] Preflight check...');
  const check = await oracle.preflight('oracle-1', {
    requiredPermission: 'InferenceSubmit',
    amountQFC: fee.baseFee,
  });
  console.log(`  Allowed: ${check.allowed}`);
  if (check.warnings.length > 0) {
    console.log(`  Warnings: ${check.warnings.join('; ')}`);
  }

  // Answer a query
  console.log('\n[4/5] Answering query via inference...');
  const result = await oracle.submitInference(
    'qfc-embed-small',
    'TextEmbedding',
    'What is the current gas price trend on QFC network?',
    '1',
  );
  console.log(`Task: ${result.taskId} — Status: ${result.status.status}`);

  // Check remaining budget
  console.log('\n[5/5] Agent spending report:');
  const info = await oracle.status('oracle-1');
  console.log(`  Deposit remaining: ${info.deposit} QFC`);
  console.log(`  Spent today: ${info.spentToday} QFC`);
  console.log(`  Daily budget left: ${(parseFloat(info.dailyLimit) - parseFloat(info.spentToday)).toFixed(4)} QFC`);

  console.log('\nDemo complete.');
}

main().catch((err) => {
  console.error('Error:', err.message);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Demo: Autonomous Trader Agent
 *
 * Shows how an AI agent can:
 * 1. Be registered by an owner with Transfer + InferenceSubmit permissions
 * 2. Receive a session key (no owner key needed after this point)
 * 3. Run sentiment analysis via inference
 * 4. Execute trades based on results
 *
 * Usage:
 *   export OWNER_PRIVATE_KEY=0x...
 *   node scripts/demo-autonomous-trader.mjs
 */

import { ethers } from 'ethers';
import { AgentWalletClient } from '../dist/agent-wallet.js';

const NETWORK = 'testnet';

async function main() {
  const ownerKey = process.env.OWNER_PRIVATE_KEY;
  if (!ownerKey) {
    console.error('Set OWNER_PRIVATE_KEY environment variable');
    process.exit(1);
  }

  const ownerWallet = new ethers.Wallet(ownerKey);
  console.log(`Owner: ${ownerWallet.address}`);

  // --- Phase 1: Owner sets up the agent ---

  const client = new AgentWalletClient(NETWORK);

  // Generate a session key for the agent
  const sessionWallet = ethers.Wallet.createRandom();
  console.log(`Session key address: ${sessionWallet.address}`);

  // Register the agent
  console.log('\n[1/4] Registering agent...');
  const reg = await client.register(ownerWallet, {
    agentId: 'trader-1',
    agentAddress: sessionWallet.address,
    permissions: ['InferenceSubmit', 'Transfer'],
    dailyLimitQFC: '100',
    maxPerTxQFC: '10',
    depositQFC: '50',
  });
  console.log(`Registered: ${reg.explorerUrl}`);

  // Issue session key (valid for 24 hours)
  console.log('\n[2/4] Issuing session key...');
  const keyTx = await client.issueSessionKey(ownerWallet, {
    agentId: 'trader-1',
    sessionKeyAddress: sessionWallet.address,
    durationSeconds: 86400,
  });
  console.log(`Session key issued: ${keyTx.explorerUrl}`);

  // --- Phase 2: Agent operates autonomously ---

  const agentClient = new AgentWalletClient(NETWORK, {
    privateKey: sessionWallet.privateKey,
    agentId: 'trader-1',
  });

  // Run sentiment analysis
  console.log('\n[3/4] Submitting inference (sentiment analysis)...');
  const result = await agentClient.submitInference(
    'qfc-embed-small',
    'TextEmbedding',
    'Bitcoin price surging, market sentiment very bullish, institutional buying detected',
    '0.1',
  );
  console.log(`Task: ${result.taskId} — Status: ${result.status.status}`);
  if (result.decoded) {
    console.log('Result:', JSON.stringify(result.decoded.output, null, 2));
  }

  // Check agent status
  console.log('\n[4/4] Agent status:');
  const info = await agentClient.status('trader-1');
  console.log(`  Active: ${info.active}`);
  console.log(`  Deposit: ${info.deposit} QFC`);
  console.log(`  Spent today: ${info.spentToday} QFC`);
  console.log(`  Daily limit: ${info.dailyLimit} QFC`);

  console.log('\nDemo complete.');
}

main().catch((err) => {
  console.error('Error:', err.message);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Demo: Content Generator Agent
 *
 * Shows how an AI agent with INFERENCE-only permission can:
 * 1. Be registered with minimal permissions (InferenceSubmit only)
 * 2. Generate content on a schedule using session keys
 * 3. Cannot transfer funds (permission denied)
 *
 * Usage:
 *   export OWNER_PRIVATE_KEY=0x...
 *   node scripts/demo-content-generator.mjs
 */

import { ethers } from 'ethers';
import { AgentWalletClient } from '../dist/agent-wallet.js';

const NETWORK = 'testnet';

async function main() {
  const ownerKey = process.env.OWNER_PRIVATE_KEY;
  if (!ownerKey) {
    console.error('Set OWNER_PRIVATE_KEY environment variable');
    process.exit(1);
  }

  const ownerWallet = new ethers.Wallet(ownerKey);
  const sessionWallet = ethers.Wallet.createRandom();

  console.log(`Owner: ${ownerWallet.address}`);
  console.log(`Session key: ${sessionWallet.address}`);

  // --- Owner setup ---

  const client = new AgentWalletClient(NETWORK);

  console.log('\n[1/3] Registering content-gen agent (InferenceSubmit only)...');
  const reg = await client.register(ownerWallet, {
    agentId: 'content-gen-1',
    agentAddress: sessionWallet.address,
    permissions: ['InferenceSubmit'],  // No Transfer!
    dailyLimitQFC: '10',
    maxPerTxQFC: '1',
    depositQFC: '5',
  });
  console.log(`Registered: ${reg.explorerUrl}`);

  await client.issueSessionKey(ownerWallet, {
    agentId: 'content-gen-1',
    sessionKeyAddress: sessionWallet.address,
    durationSeconds: 86400 * 7, // 7 days
  });
  console.log('Session key issued (7 day TTL)');

  // --- Agent generates content ---

  const agentClient = new AgentWalletClient(NETWORK, {
    privateKey: sessionWallet.privateKey,
    agentId: 'content-gen-1',
  });

  console.log('\n[2/3] Generating content via inference...');
  const result = await agentClient.submitInference(
    'qfc-embed-small',
    'TextGeneration',
    'Write a short blog post about decentralized AI compute networks',
    '0.5',
  );
  console.log(`Task: ${result.taskId} — Status: ${result.status.status}`);

  // --- Verify Transfer permission is denied ---

  console.log('\n[3/3] Testing Transfer permission (should be denied)...');
  const check = await agentClient.preflight('content-gen-1', {
    requiredPermission: 'Transfer',
    amountQFC: '1',
  });
  console.log(`Transfer allowed: ${check.allowed}`);
  if (!check.allowed) {
    console.log(`Denied reasons: ${check.reasons.join('; ')}`);
  }

  console.log('\nDemo complete.');
}

main().catch((err) => {
  console.error('Error:', err.message);
  process.exit(1);
});

#!/usr/bin/env node

// Example: QFC Discord Bot using discord.js
// Install: npm install discord.js
// Run:     DISCORD_TOKEN=your_token node scripts/discord-bot-example.mjs
//
// This file is a usage example only — discord.js is NOT a dependency of this package.

import { Client, GatewayIntentBits } from 'discord.js';
import { QFCDiscordBot } from '../dist/discord.js';

const DISCORD_TOKEN = process.env.DISCORD_TOKEN;
if (!DISCORD_TOKEN) {
  console.error('Error: Set the DISCORD_TOKEN environment variable.');
  process.exit(1);
}

// Use testnet by default; set QFC_NETWORK=mainnet to override
const network = process.env.QFC_NETWORK === 'mainnet' ? 'mainnet' : 'testnet';
const bot = new QFCDiscordBot(network);

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.once('ready', () => {
  console.log(`QFC Bot logged in as ${client.user.tag} (network: ${network})`);
});

client.on('messageCreate', async (message) => {
  // Ignore bot messages
  if (message.author.bot) return;

  const response = await bot.handleMessage(message.content);
  if (response) {
    await message.reply(response.message);
  }
});

client.login(DISCORD_TOKEN);

import { ethers } from 'ethers';
import { NetworkName, createProvider, rpcCall } from './provider.js';
import {
  QFCAgent,
  AgentInfo,
  AgentTxResult,
  RegisterAgentResult,
  AgentPermission,
  SessionKeyInfo,
  PreflightResult,
} from './agent.js';
import { QFCInference, InferenceTaskStatus, DecodedResult, FeeEstimate } from './inference.js';

/** Options for registering a new agent */
export interface RegisterAgentOptions {
  agentId: string;
  agentAddress: string;
  permissions: AgentPermission[];
  dailyLimitQFC: string;
  maxPerTxQFC: string;
  depositQFC: string;
}

/** Session key configuration for the client */
export interface SessionKeyConfig {
  /** Private key of the session key (hex) */
  privateKey: string;
  /** Agent ID this session key belongs to */
  agentId: string;
}

/** Options for issuing a session key */
export interface IssueSessionKeyOptions {
  agentId: string;
  /** Address of the session key (derived from its private key) */
  sessionKeyAddress: string;
  /** Duration in seconds */
  durationSeconds: number;
}

/** Result from session-key-aware inference submission */
export interface AgentInferenceResult {
  taskId: string;
  status: InferenceTaskStatus;
  decoded?: DecodedResult;
}

/**
 * AgentWalletClient — high-level client for AI agent wallet operations.
 *
 * Wraps QFCAgent (on-chain registry) and QFCInference (task submission)
 * to enable session-key-aware operations. An agent can submit inference
 * tasks using a session key instead of the owner's long-lived private key.
 *
 * @example
 * ```ts
 * // Owner registers agent and issues session key
 * const client = new AgentWalletClient('testnet');
 * const ownerWallet = new ethers.Wallet(OWNER_KEY);
 * await client.register(ownerWallet, {
 *   agentId: 'trader-1',
 *   agentAddress: sessionWallet.address,
 *   permissions: ['InferenceSubmit', 'Transfer'],
 *   dailyLimitQFC: '100',
 *   maxPerTxQFC: '10',
 *   depositQFC: '50',
 * });
 * await client.issueSessionKey(ownerWallet, {
 *   agentId: 'trader-1',
 *   sessionKeyAddress: sessionWallet.address,
 *   durationSeconds: 86400,
 * });
 *
 * // Agent operates autonomously with session key (no owner key needed)
 * const agentClient = new AgentWalletClient('testnet', {
 *   privateKey: SESSION_PRIVATE_KEY,
 *   agentId: 'trader-1',
 * });
 * const result = await agentClient.submitInference(
 *   'qfc-embed-small', 'TextEmbedding', 'analyze market sentiment', '0.1',
 * );
 * ```
 */
export class AgentWalletClient {
  private agent: QFCAgent;
  private inference: QFCInference;
  private network: NetworkName;
  private sessionKey?: SessionKeyConfig;
  private sessionWallet?: ethers.Wallet;

  constructor(network: NetworkName = 'testnet', sessionKey?: SessionKeyConfig) {
    this.network = network;
    this.agent = new QFCAgent(network);
    this.inference = new QFCInference(network);

    if (sessionKey) {
      this.sessionKey = sessionKey;
      this.sessionWallet = new ethers.Wallet(sessionKey.privateKey);
    }
  }

  // ===================================================
  // Agent Lifecycle (owner operations)
  // ===================================================

  /** Register a new agent on-chain. Requires owner signer. */
  async register(
    ownerSigner: ethers.Signer,
    opts: RegisterAgentOptions,
  ): Promise<RegisterAgentResult> {
    return this.agent.registerAgent(
      ownerSigner,
      opts.agentId,
      opts.agentAddress,
      opts.permissions,
      opts.dailyLimitQFC,
      opts.maxPerTxQFC,
      opts.depositQFC,
    );
  }

  /** Fund an agent with additional QFC. Requires owner signer. */
  async fund(
    ownerSigner: ethers.Signer,
    agentId: string,
    amountQFC: string,
  ): Promise<AgentTxResult> {
    return this.agent.fundAgent(ownerSigner, agentId, amountQFC);
  }

  /** Revoke an agent, deactivating it. Requires owner signer. */
  async revoke(
    ownerSigner: ethers.Signer,
    agentId: string,
  ): Promise<AgentTxResult> {
    return this.agent.revokeAgent(ownerSigner, agentId);
  }

  /** Get agent info by ID. */
  async status(agentId: string): Promise<AgentInfo> {
    return this.agent.getAgent(agentId);
  }

  /** List all agent IDs owned by an address. */
  async list(ownerAddress: string): Promise<string[]> {
    return this.agent.listAgents(ownerAddress);
  }

  // ===================================================
  // Session Key Management (owner operations)
  // ===================================================

  /** Issue a session key for an agent. Requires owner signer. */
  async issueSessionKey(
    ownerSigner: ethers.Signer,
    opts: IssueSessionKeyOptions,
  ): Promise<AgentTxResult> {
    return this.agent.issueSessionKey(
      ownerSigner,
      opts.agentId,
      opts.sessionKeyAddress,
      opts.durationSeconds,
    );
  }

  /** Rotate a session key: revoke old, issue new. Requires owner signer. */
  async rotateSessionKey(
    ownerSigner: ethers.Signer,
    agentId: string,
    oldKeyAddress: string,
    newKeyAddress: string,
    durationSeconds: number,
  ): Promise<AgentTxResult> {
    return this.agent.rotateSessionKey(
      ownerSigner,
      agentId,
      oldKeyAddress,
      newKeyAddress,
      durationSeconds,
    );
  }

  /** Revoke a session key. Requires owner signer. */
  async revokeSessionKey(
    ownerSigner: ethers.Signer,
    agentId: string,
    keyAddress: string,
  ): Promise<AgentTxResult> {
    return this.agent.revokeSessionKey(ownerSigner, agentId, keyAddress);
  }

  /** Get session key info. */
  async getSessionKey(agentId: string, keyAddress: string): Promise<SessionKeyInfo> {
    return this.agent.getSessionKey(agentId, keyAddress);
  }

  /** Check if a session key is still valid. */
  async isSessionKeyValid(keyAddress: string): Promise<boolean> {
    return this.agent.isSessionKeyValid(keyAddress);
  }

  // ===================================================
  // Session-Key-Aware Inference (agent operations)
  // ===================================================

  /**
   * Submit an inference task using the session key (no owner key needed).
   *
   * The task is signed by the session key wallet. The on-chain registry
   * validates that the session key is authorized for the agent and has
   * the InferenceSubmit permission.
   *
   * @param modelId - Model ID (e.g. "qfc-embed-small")
   * @param taskType - Task type (e.g. "TextEmbedding", "TextGeneration")
   * @param input - Input text
   * @param maxFeeQFC - Maximum fee in QFC
   * @param opts - Optional: waitForResult (default true), timeoutMs
   */
  async submitInference(
    modelId: string,
    taskType: string,
    input: string,
    maxFeeQFC: string,
    opts?: { waitForResult?: boolean; timeoutMs?: number },
  ): Promise<AgentInferenceResult> {
    if (!this.sessionKey || !this.sessionWallet) {
      throw new Error(
        'No session key configured. Create AgentWalletClient with a SessionKeyConfig to use session-key inference.',
      );
    }

    // Preflight: verify agent is active and session key is valid
    const preflight = await this.agent.preflight({
      agentId: this.sessionKey.agentId,
      requiredPermission: 'InferenceSubmit',
      amountQFC: maxFeeQFC,
      sessionKeyAddress: this.sessionWallet.address,
    });

    if (!preflight.allowed) {
      throw new Error(
        `Preflight denied: ${preflight.reasons.join('; ')}`,
      );
    }

    // Submit task signed by the session key wallet
    const provider = createProvider(this.network);
    const connectedWallet = this.sessionWallet.connect(provider);
    const taskId = await this.inference.submitTask(
      modelId,
      taskType,
      input,
      maxFeeQFC,
      connectedWallet,
    );

    // Optionally wait for result
    const shouldWait = opts?.waitForResult !== false;
    if (shouldWait) {
      const status = await this.inference.waitForResult(
        taskId,
        opts?.timeoutMs ?? 120_000,
      );
      let decoded: DecodedResult | undefined;
      if (status.status === 'Completed' && status.result) {
        try {
          decoded = this.inference.decodeResult(status.result);
        } catch {
          // result may be in IPFS — caller can fetch separately
        }
      }
      return { taskId, status, decoded };
    }

    const status = await this.inference.getTaskStatus(taskId);
    return { taskId, status };
  }

  /** Estimate fee for an inference task. */
  async estimateFee(
    modelId: string,
    taskType?: string,
    inputSize?: number,
  ): Promise<FeeEstimate> {
    return this.inference.estimateFee(modelId, taskType, inputSize);
  }

  /** Get the session key wallet address (if configured). */
  get sessionKeyAddress(): string | undefined {
    return this.sessionWallet?.address;
  }

  /** Get the agent ID associated with the session key (if configured). */
  get agentId(): string | undefined {
    return this.sessionKey?.agentId;
  }

  // ===================================================
  // Safe Execution (preflight + execute)
  // ===================================================

  /** Run preflight checks without submitting. */
  async preflight(agentId: string, opts?: {
    requiredPermission?: AgentPermission;
    amountQFC?: string;
    sessionKeyAddress?: string;
  }): Promise<PreflightResult> {
    return this.agent.preflight({
      agentId,
      ...opts,
      sessionKeyAddress: opts?.sessionKeyAddress ?? this.sessionWallet?.address,
    });
  }

  /**
   * Safely fund an agent: run preflight checks, then fund if allowed.
   * In dry-run mode, returns only the preflight result.
   */
  async safeFund(
    ownerSigner: ethers.Signer,
    agentId: string,
    amountQFC: string,
    opts?: { dryRun?: boolean },
  ): Promise<{ preflight: PreflightResult; tx?: AgentTxResult }> {
    return this.agent.safeFundAgent(ownerSigner, agentId, amountQFC, {
      dryRun: opts?.dryRun,
      sessionKeyAddress: this.sessionWallet?.address,
    });
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig } from './provider.js';

/**
 * Permission enum values matching the AgentRegistry contract.
 * 0 = InferenceSubmit, 1 = Transfer, 2 = StakeDelegate, 3 = QueryOnly
 */
export type AgentPermission = 'InferenceSubmit' | 'Transfer' | 'StakeDelegate' | 'QueryOnly';

const PERMISSION_VALUES: Record<AgentPermission, number> = {
  InferenceSubmit: 0,
  Transfer: 1,
  StakeDelegate: 2,
  QueryOnly: 3,
};

/** Agent info returned by getAgent */
export interface AgentInfo {
  agentId: string;
  owner: string;
  agentAddress: string;
  permissions: number[];
  dailyLimit: string;
  maxPerTx: string;
  deposit: string;
  spentToday: string;
  lastSpendDay: bigint;
  registeredAt: bigint;
  active: boolean;
}

/** Session key info returned by getSessionKey */
export interface SessionKeyInfo {
  agentId: string;
  keyAddress: string;
  expiresAt: bigint;
  active: boolean;
}

/** Result from register/fund/revoke/session-key write operations */
export interface AgentTxResult {
  txHash: string;
  explorerUrl: string;
}

/** Result from registerAgent (includes agentId) */
export interface RegisterAgentResult extends AgentTxResult {
  agentId: string;
}

/** Reverse mapping from numeric permission to name */
const PERMISSION_NAMES: Record<number, AgentPermission> = {
  0: 'InferenceSubmit',
  1: 'Transfer',
  2: 'StakeDelegate',
  3: 'QueryOnly',
};

/** Preflight check result — returned before tx submission */
export interface PreflightResult {
  allowed: boolean;
  reasons: string[];
  warnings: string[];
  agent: AgentInfo | null;
  sessionKeyValid?: boolean;
}

/** Options for preflight policy check */
export interface PreflightOptions {
  agentId: string;
  /** Permission required for the operation */
  requiredPermission?: AgentPermission;
  /** Amount in QFC the operation will spend */
  amountQFC?: string;
  /** Session key address to validate (optional) */
  sessionKeyAddress?: string;
}

/** Registry addresses per network */
const REGISTRY_ADDRESS: Record<NetworkName, string> = {
  testnet: '0x7791dfa4d489f3d524708cbc0caa8689b76322b3',
  mainnet: '0x0000000000000000000000000000000000000000', // TBD
};

const AGENT_REGISTRY_ABI = [
  'function registerAgent(string agentId, address agentAddress, uint8[] permissions, uint256 dailyLimit, uint256 maxPerTx) payable returns (string)',
  'function fundAgent(string agentId) payable',
  'function revokeAgent(string agentId)',
  'function getAgent(string agentId) view returns (tuple(string agentId, address owner, address agentAddress, uint8[] permissions, uint256 dailyLimit, uint256 maxPerTx, uint256 deposit, uint256 spentToday, uint256 lastSpendDay, uint256 registeredAt, bool active))',
  'function getAgentsByOwner(address owner) view returns (string[])',
  'function issueSessionKey(string agentId, address sessionKeyAddress, uint256 durationSeconds)',
  'function rotateSessionKey(string agentId, address oldKeyAddress, address newKeyAddress, uint256 durationSeconds)',
  'function revokeSessionKey(string agentId, address keyAddress)',
  'function getSessionKey(string agentId, address keyAddress) view returns (tuple(string agentId, address keyAddress, uint256 expiresAt, bool active))',
  'function isSessionKeyValid(address keyAddress) view returns (bool)',
];

/**
 * QFCAgent — AI Agent Registry interaction.
 *
 * Manages on-chain agent accounts: registration, funding, revocation,
 * session key lifecycle (issue, rotate, revoke, validate), and querying agent info.
 *
 * @example
 * ```ts
 * const agent = new QFCAgent('testnet');
 * // Register
 * const result = await agent.registerAgent(signer, 'my-agent', agentAddr, ['Transfer'], '100', '10', '5');
 * // Issue session key
 * await agent.issueSessionKey(signer, 'my-agent', sessionAddr, 3600);
 * // Rotate session key
 * await agent.rotateSessionKey(signer, 'my-agent', oldAddr, newAddr, 3600);
 * // Revoke session key
 * await agent.revokeSessionKey(signer, 'my-agent', sessionAddr);
 * ```
 */
export class QFCAgent {
  private provider: ethers.JsonRpcProvider;
  private registryAddress: string;
  private network: NetworkName;
  private networkConfig;

  constructor(network: NetworkName = 'testnet') {
    this.network = network;
    this.provider = createProvider(network);
    this.networkConfig = getNetworkConfig(network);
    this.registryAddress = REGISTRY_ADDRESS[network];
  }

  private getContract(signerOrProvider?: ethers.Signer | ethers.Provider): ethers.Contract {
    return new ethers.Contract(
      this.registryAddress,
      AGENT_REGISTRY_ABI,
      signerOrProvider ?? this.provider,
    );
  }

  /** Poll for transaction receipt via raw RPC (avoids ethers.js log-parsing issues on QFC) */
  private async waitForReceipt(
    txHash: string,
    timeoutMs: number = 120_000,
  ): Promise<{ status: string; blockNumber: string; gasUsed: string }> {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, 3000));
      const raw = await this.provider.send('eth_getTransactionReceipt', [txHash]);
      if (raw) return raw;
    }
    throw new Error(`Transaction ${txHash} not confirmed after ${timeoutMs / 1000}s`);
  }

  private explorerTxUrl(txHash: string): string {
    return `${this.networkConfig.explorerUrl}/txs/${txHash}`;
  }

  private requireAgentId(agentId: string): void {
    if (!agentId || agentId.trim().length === 0) {
      throw new Error('agentId must be a non-empty string.');
    }
  }

  private requireAddress(address: string, label: string): void {
    if (!ethers.isAddress(address)) {
      throw new Error(`Invalid ${label} format. Expected 0x + 40 hex characters.`);
    }
  }

  private requirePositiveAmount(value: string, label: string): void {
    const parsed = parseFloat(value);
    if (isNaN(parsed) || parsed <= 0) {
      throw new Error(`${label} must be a positive number.`);
    }
  }

  /**
   * Register a new AI agent on the registry.
   * @param ownerSigner - wallet of the agent owner
   * @param agentId - unique string identifier for the agent
   * @param agentAddress - the agent's on-chain address
   * @param permissions - array of permission types
   * @param dailyLimitQFC - daily spending limit in QFC
   * @param maxPerTxQFC - max spend per transaction in QFC
   * @param depositQFC - initial deposit in QFC (sent as msg.value)
   */
  async registerAgent(
    ownerSigner: ethers.Signer,
    agentId: string,
    agentAddress: string,
    permissions: AgentPermission[],
    dailyLimitQFC: string,
    maxPerTxQFC: string,
    depositQFC: string,
  ): Promise<RegisterAgentResult> {
    this.requireAgentId(agentId);
    this.requireAddress(agentAddress, 'agentAddress');
    this.requirePositiveAmount(dailyLimitQFC, 'dailyLimitQFC');
    this.requirePositiveAmount(maxPerTxQFC, 'maxPerTxQFC');
    this.requirePositiveAmount(depositQFC, 'depositQFC');
    if (permissions.length === 0) {
      throw new Error('At least one permission is required.');
    }

    const connected = ownerSigner.connect(this.provider);
    const contract = this.getContract(connected);
    const permissionValues = permissions.map((p) => PERMISSION_VALUES[p]);

    const tx = await contract.registerAgent(
      agentId,
      agentAddress,
      permissionValues,
      ethers.parseEther(dailyLimitQFC),
      ethers.parseEther(maxPerTxQFC),
      { value: ethers.parseEther(depositQFC), gasLimit: 500_000 },
    );

    const receipt = await this.waitForReceipt(tx.hash);
    if (receipt.status !== '0x1') {
      throw new Error(`registerAgent reverted (tx: ${tx.hash})`);
    }

    return { txHash: tx.hash, agentId, explorerUrl: this.explorerTxUrl(tx.hash) };
  }

  /**
   * Fund an existing agent with additional QFC.
   */
  async fundAgent(
    ownerSigner: ethers.Signer,
    agentId: string,
    amountQFC: string,
  ): Promise<AgentTxResult> {
    this.requireAgentId(agentId);
    this.requirePositiveAmount(amountQFC, 'amountQFC');

    const connected = ownerSigner.connect(this.provider);
    const contract = this.getContract(connected);

    const tx = await contract.fundAgent(agentId, {
      value: ethers.parseEther(amountQFC),
      gasLimit: 200_000,
    });

    const receipt = await this.waitForReceipt(tx.hash);
    if (receipt.status !== '0x1') {
      throw new Error(`fundAgent reverted (tx: ${tx.hash})`);
    }

    return { txHash: tx.hash, explorerUrl: this.explorerTxUrl(tx.hash) };
  }

  /**
   * Revoke an agent, deactivating it on the registry.
   */
  async revokeAgent(
    ownerSigner: ethers.Signer,
    agentId: string,
  ): Promise<AgentTxResult> {
    this.requireAgentId(agentId);

    const connected = ownerSigner.connect(this.provider);
    const contract = this.getContract(connected);

    const tx = await contract.revokeAgent(agentId, { gasLimit: 200_000 });

    const receipt = await this.waitForReceipt(tx.hash);
    if (receipt.status !== '0x1') {
      throw new Error(`revokeAgent reverted (tx: ${tx.hash})`);
    }

    return { txHash: tx.hash, explorerUrl: this.explorerTxUrl(tx.hash) };
  }

  /**
   * Get agent info by ID.
   */
  async getAgent(agentId: string): Promise<AgentInfo> {
    this.requireAgentId(agentId);

    const contract = this.getContract(this.provider);
    const result = await contract.getAgent(agentId);

    return {
      agentId: result.agentId,
      owner: result.owner,
      agentAddress: result.agentAddress,
      permissions: Array.from(result.permissions).map(Number),
      dailyLimit: ethers.formatEther(result.dailyLimit),
      maxPerTx: ethers.formatEther(result.maxPerTx),
      deposit: ethers.formatEther(result.deposit),
      spentToday: ethers.formatEther(result.spentToday),
      lastSpendDay: BigInt(result.lastSpendDay),
      registeredAt: BigInt(result.registeredAt),
      active: result.active,
    };
  }

  /**
   * List all agent IDs owned by an address.
   */
  async listAgents(ownerAddress: string): Promise<string[]> {
    this.requireAddress(ownerAddress, 'ownerAddress');

    const contract = this.getContract(this.provider);
    return contract.getAgentsByOwner(ownerAddress);
  }

  /**
   * Issue a session key for an agent.
   * @param durationSeconds - how long the session key is valid (must be > 0)
   */
  async issueSessionKey(
    ownerSigner: ethers.Signer,
    agentId: string,
    sessionKeyAddress: string,
    durationSeconds: number,
  ): Promise<AgentTxResult> {
    this.requireAgentId(agentId);
    this.requireAddress(sessionKeyAddress, 'sessionKeyAddress');
    if (!Number.isInteger(durationSeconds) || durationSeconds <= 0) {
      throw new Error('durationSeconds must be a positive integer.');
    }

    const connected = ownerSigner.connect(this.provider);
    const contract = this.getContract(connected);

    const tx = await contract.issueSessionKey(agentId, sessionKeyAddress, durationSeconds, {
      gasLimit: 200_000,
    });

    const receipt = await this.waitForReceipt(tx.hash);
    if (receipt.status !== '0x1') {
      throw new Error(`issueSessionKey reverted (tx: ${tx.hash})`);
    }

    return { txHash: tx.hash, explorerUrl: this.explorerTxUrl(tx.hash) };
  }

  /**
   * Rotate a session key: atomically revoke the old key and issue a new one.
   * @param oldKeyAddress - the session key address to revoke
   * @param newKeyAddress - the new session key address to authorize
   * @param durationSeconds - validity period for the new key (must be > 0)
   */
  async rotateSessionKey(
    ownerSigner: ethers.Signer,
    agentId: string,
    oldKeyAddress: string,
    newKeyAddress: string,
    durationSeconds: number,
  ): Promise<AgentTxResult> {
    this.requireAgentId(agentId);
    this.requireAddress(oldKeyAddress, 'oldKeyAddress');
    this.requireAddress(newKeyAddress, 'newKeyAddress');
    if (oldKeyAddress.toLowerCase() === newKeyAddress.toLowerCase()) {
      throw new Error('newKeyAddress must differ from oldKeyAddress.');
    }
    if (!Number.isInteger(durationSeconds) || durationSeconds <= 0) {
      throw new Error('durationSeconds must be a positive integer.');
    }

    const connected = ownerSigner.connect(this.provider);
    const contract = this.getContract(connected);

    const tx = await contract.rotateSessionKey(
      agentId,
      oldKeyAddress,
      newKeyAddress,
      durationSeconds,
      { gasLimit: 300_000 },
    );

    const receipt = await this.waitForReceipt(tx.hash);
    if (receipt.status !== '0x1') {
      throw new Error(`rotateSessionKey reverted (tx: ${tx.hash})`);
    }

    return { txHash: tx.hash, explorerUrl: this.explorerTxUrl(tx.hash) };
  }

  /**
   * Revoke a session key, immediately deactivating it.
   */
  async revokeSessionKey(
    ownerSigner: ethers.Signer,
    agentId: string,
    keyAddress: string,
  ): Promise<AgentTxResult> {
    this.requireAgentId(agentId);
    this.requireAddress(keyAddress, 'keyAddress');

    const connected = ownerSigner.connect(this.provider);
    const contract = this.getContract(connected);

    const tx = await contract.revokeSessionKey(agentId, keyAddress, { gasLimit: 200_000 });

    const receipt = await this.waitForReceipt(tx.hash);
    if (receipt.status !== '0x1') {
      throw new Error(`revokeSessionKey reverted (tx: ${tx.hash})`);
    }

    return { txHash: tx.hash, explorerUrl: this.explorerTxUrl(tx.hash) };
  }

  /**
   * Get session key details for an agent.
   */
  async getSessionKey(agentId: string, keyAddress: string): Promise<SessionKeyInfo> {
    this.requireAgentId(agentId);
    this.requireAddress(keyAddress, 'keyAddress');

    const contract = this.getContract(this.provider);
    const result = await contract.getSessionKey(agentId, keyAddress);

    return {
      agentId: result.agentId,
      keyAddress: result.keyAddress,
      expiresAt: BigInt(result.expiresAt),
      active: result.active,
    };
  }

  /**
   * Check if a session key address is still valid.
   */
  async isSessionKeyValid(keyAddress: string): Promise<boolean> {
    this.requireAddress(keyAddress, 'keyAddress');

    const contract = this.getContract(this.provider);
    return contract.isSessionKeyValid(keyAddress);
  }

  // ===================================================
  // Safe Execution Mode — preflight policy checks
  // ===================================================

  /**
   * Run preflight policy checks against on-chain state before submitting a tx.
   * Returns whether the operation is allowed with human-readable deny reasons.
   *
   * Checks performed:
   * - Agent exists and is active
   * - Required permission is granted
   * - Amount within per-tx limit (maxPerTx)
   * - Amount within remaining daily budget (dailyLimit − spentToday)
   * - Sufficient deposit balance
   * - Session key validity (if provided)
   */
  async preflight(opts: PreflightOptions): Promise<PreflightResult> {
    this.requireAgentId(opts.agentId);

    const reasons: string[] = [];
    const warnings: string[] = [];
    let agent: AgentInfo | null = null;
    let sessionKeyValid: boolean | undefined;

    // 1. Fetch agent from chain
    try {
      agent = await this.getAgent(opts.agentId);
    } catch {
      return { allowed: false, reasons: [`Agent "${opts.agentId}" not found on-chain.`], warnings, agent: null };
    }

    // 2. Active check
    if (!agent.active) {
      reasons.push(`Agent "${opts.agentId}" is revoked/inactive.`);
    }

    // 3. Permission check
    if (opts.requiredPermission) {
      const requiredValue = PERMISSION_VALUES[opts.requiredPermission];
      if (!agent.permissions.includes(requiredValue)) {
        const granted = agent.permissions
          .map((p) => PERMISSION_NAMES[p] ?? `unknown(${p})`)
          .join(', ');
        reasons.push(
          `Missing permission "${opts.requiredPermission}". Agent has: [${granted}].`,
        );
      }
    }

    // 4. Amount checks (if spending QFC)
    if (opts.amountQFC) {
      const amount = parseFloat(opts.amountQFC);
      const maxPerTx = parseFloat(agent.maxPerTx);
      const dailyLimit = parseFloat(agent.dailyLimit);
      const spentToday = parseFloat(agent.spentToday);
      const deposit = parseFloat(agent.deposit);

      if (amount > maxPerTx) {
        reasons.push(
          `Amount ${opts.amountQFC} QFC exceeds per-tx limit of ${agent.maxPerTx} QFC.`,
        );
      }

      const remainingDaily = dailyLimit - spentToday;
      if (amount > remainingDaily) {
        reasons.push(
          `Amount ${opts.amountQFC} QFC exceeds remaining daily budget of ${remainingDaily.toFixed(4)} QFC (limit: ${agent.dailyLimit}, spent: ${agent.spentToday}).`,
        );
      } else if (amount > remainingDaily * 0.8) {
        warnings.push(
          `This tx uses ${((amount / remainingDaily) * 100).toFixed(0)}% of remaining daily budget (${remainingDaily.toFixed(4)} QFC left).`,
        );
      }

      if (amount > deposit) {
        reasons.push(
          `Insufficient deposit: ${agent.deposit} QFC available, ${opts.amountQFC} QFC required.`,
        );
      } else if (amount > deposit * 0.9) {
        warnings.push(
          `Deposit nearly depleted: ${agent.deposit} QFC remaining after this tx.`,
        );
      }
    }

    // 5. Session key check (if provided)
    if (opts.sessionKeyAddress) {
      this.requireAddress(opts.sessionKeyAddress, 'sessionKeyAddress');
      try {
        sessionKeyValid = await this.isSessionKeyValid(opts.sessionKeyAddress);
        if (!sessionKeyValid) {
          reasons.push(
            `Session key ${opts.sessionKeyAddress} is expired or revoked.`,
          );
        }
      } catch {
        warnings.push(`Could not verify session key ${opts.sessionKeyAddress} (RPC error).`);
      }
    }

    return {
      allowed: reasons.length === 0,
      reasons,
      warnings,
      agent,
      sessionKeyValid,
    };
  }

  /**
   * Fund an agent with preflight policy checks (safe mode).
   * In dry-run mode, returns the preflight result without submitting the tx.
   */
  async safeFundAgent(
    ownerSigner: ethers.Signer,
    agentId: string,
    amountQFC: string,
    opts?: { dryRun?: boolean; sessionKeyAddress?: string },
  ): Promise<{ preflight: PreflightResult; tx?: AgentTxResult }> {
    const check = await this.preflight({
      agentId,
      amountQFC,
      requiredPermission: 'Transfer',
      sessionKeyAddress: opts?.sessionKeyAddress,
    });

    if (opts?.dryRun || !check.allowed) {
      return { preflight: check };
    }

    const tx = await this.fundAgent(ownerSigner, agentId, amountQFC);
    return { preflight: check, tx };
  }

  /**
   * Generic safe execution wrapper: run preflight, then execute a callback if allowed.
   * In dry-run mode, returns the preflight result without executing.
   *
   * @example
   * ```ts
   * const result = await agent.safeExecute(
   *   { agentId: 'my-agent', requiredPermission: 'Transfer', amountQFC: '5' },
   *   async () => agent.fundAgent(signer, 'my-agent', '5'),
   * );
   * if (!result.preflight.allowed) {
   *   console.log('Denied:', result.preflight.reasons);
   * }
   * ```
   */
  async safeExecute<T>(
    opts: PreflightOptions & { dryRun?: boolean },
    execute: () => Promise<T>,
  ): Promise<{ preflight: PreflightResult; result?: T }> {
    const check = await this.preflight(opts);

    if (opts.dryRun || !check.allowed) {
      return { preflight: check };
    }

    const result = await execute();
    return { preflight: check, result };
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig } from './provider.js';

export interface BlockInfo {
  number: number;
  hash: string;
  parentHash: string;
  timestamp: number;
  miner: string;
  gasUsed: number;
  gasLimit: number;
  transactionCount: number;
  stateRoot: string;
}

export interface TransactionInfo {
  hash: string;
  from: string;
  to: string | null;
  value: string;
  gasPrice: string;
  blockNumber: number | null;
  status: 'pending' | 'confirmed';
}

export interface ReceiptInfo {
  txHash: string;
  blockNumber: number;
  from: string;
  to: string | null;
  gasUsed: number;
  status: 'success' | 'failed';
  contractAddress: string | null;
  logs: LogInfo[];
}

export interface LogInfo {
  address: string;
  topics: string[];
  data: string;
}

/**
 * QFCChain — query blocks, transactions, and receipts on QFC.
 */
export class QFCChain {
  private provider: ethers.JsonRpcProvider;

  constructor(network: NetworkName = 'testnet') {
    this.provider = createProvider(network);
  }

  /** Get the latest block number */
  async getBlockNumber(): Promise<number> {
    return this.provider.getBlockNumber();
  }

  /** Get block info by number or 'latest' */
  async getBlock(blockNumber: number | 'latest'): Promise<BlockInfo> {
    const tag = blockNumber === 'latest' ? 'latest' : blockNumber;
    const block = await this.provider.getBlock(tag);
    if (!block) {
      throw new Error(`Block not found: ${blockNumber}`);
    }
    return {
      number: block.number,
      hash: block.hash!,
      parentHash: block.parentHash,
      timestamp: block.timestamp,
      miner: block.miner,
      gasUsed: Number(block.gasUsed),
      gasLimit: Number(block.gasLimit),
      transactionCount: block.transactions.length,
      stateRoot: block.stateRoot ?? '',
    };
  }

  /** Get transaction by hash */
  async getTransaction(txHash: string): Promise<TransactionInfo | null> {
    const tx = await this.provider.getTransaction(txHash);
    if (!tx) return null;
    return {
      hash: tx.hash,
      from: tx.from,
      to: tx.to,
      value: ethers.formatEther(tx.value),
      gasPrice: ethers.formatUnits(tx.gasPrice ?? 0n, 'gwei'),
      blockNumber: tx.blockNumber,
      status: tx.blockNumber != null ? 'confirmed' : 'pending',
    };
  }

  /** Get transaction receipt */
  async getReceipt(txHash: string): Promise<ReceiptInfo | null> {
    const receipt = await this.provider.getTransactionReceipt(txHash);
    if (!receipt) return null;
    return {
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
      from: receipt.from,
      to: receipt.to,
      gasUsed: Number(receipt.gasUsed),
      status: receipt.status === 1 ? 'success' : 'failed',
      contractAddress: receipt.contractAddress,
      logs: receipt.logs.map((log) => ({
        address: log.address,
        topics: log.topics as string[],
        data: log.data,
      })),
    };
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig } from './provider.js';

export interface CallResult {
  result: any;
  decoded: any[];
}

export interface SendResult {
  txHash: string;
  explorerUrl: string;
  gasUsed: number;
  logs: { address: string; topics: string[]; data: string }[];
}

export interface DeployResult {
  contractAddress: string;
  txHash: string;
  explorerUrl: string;
}

export interface VerifyResult {
  address: string;
  verified: boolean;
  contractName: string;
  compiler: string;
  evmVersion: string;
}

/**
 * QFCContract — read, write, and deploy smart contracts on QFC.
 */
export class QFCContract {
  private provider: ethers.JsonRpcProvider;
  private networkConfig;

  constructor(network: NetworkName = 'testnet') {
    this.networkConfig = getNetworkConfig(network);
    this.provider = createProvider(network);
  }

  /** Poll for transaction receipt via raw RPC (avoids ethers.js log-parsing issues on QFC) */
  private async waitForReceipt(
    txHash: string,
    timeoutMs: number = 120_000,
  ): Promise<{ status: string; hash: string; blockNumber: string; gasUsed: string; logs: Array<{ address: string; topics: string[]; data: string }> }> {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, 3000));
      const raw = await this.provider.send('eth_getTransactionReceipt', [txHash]);
      if (raw) return { ...raw, hash: txHash };
    }
    throw new Error(`Transaction ${txHash} not confirmed after ${timeoutMs / 1000}s`);
  }

  /**
   * Read contract state (no gas, no signer needed).
   * @param address - contract address
   * @param abi - ABI array or JSON string
   * @param method - method name
   * @param args - method arguments
   */
  async call(
    address: string,
    abi: ethers.InterfaceAbi,
    method: string,
    args: any[] = [],
  ): Promise<CallResult> {
    const contract = new ethers.Contract(address, abi, this.provider);
    const result = await contract[method](...args);
    const iface = new ethers.Interface(abi);
    const fragment = iface.getFunction(method);
    let decoded: any[];
    if (fragment && fragment.outputs && fragment.outputs.length > 1) {
      decoded = Array.isArray(result) ? [...result] : [result];
    } else {
      decoded = [result];
    }
    return { result, decoded };
  }

  /**
   * Write to a contract (requires signer, costs gas).
   * @param address - contract address
   * @param abi - ABI array or JSON string
   * @param method - method name
   * @param args - method arguments
   * @param signer - wallet to sign the transaction
   * @param value - optional QFC value to send (in ether units, e.g. "1.5")
   */
  async send(
    address: string,
    abi: ethers.InterfaceAbi,
    method: string,
    args: any[],
    signer: ethers.Wallet,
    value?: string,
  ): Promise<SendResult> {
    const connected = signer.connect(this.provider);
    const contract = new ethers.Contract(address, abi, connected);
    const overrides: ethers.Overrides = {};
    if (value) {
      overrides.value = ethers.parseEther(value);
    }
    const tx = await contract[method](...args, overrides);
    const receipt = await this.waitForReceipt(tx.hash);
    if (receipt.status !== '0x1') {
      throw new Error(`Transaction reverted (tx: ${tx.hash})`);
    }
    return {
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${tx.hash}`,
      gasUsed: Number(receipt.gasUsed),
      logs: (receipt.logs ?? []).map((log: { address: string; topics: string[]; data: string }) => ({
        address: log.address,
        topics: log.topics as string[],
        data: log.data,
      })),
    };
  }

  /**
   * Deploy a new contract.
   * @param abi - contract ABI
   * @param bytecode - compiled bytecode (hex string)
   * @param args - constructor arguments
   * @param signer - wallet to deploy from
   */
  async deploy(
    abi: ethers.InterfaceAbi,
    bytecode: string,
    args: any[],
    signer: ethers.Wallet,
  ): Promise<DeployResult> {
    const connected = signer.connect(this.provider);
    const factory = new ethers.ContractFactory(abi, bytecode, connected);
    const contract = await factory.deploy(...args);
    const receipt = await contract.deploymentTransaction()!.wait();
    const address = await contract.getAddress();
    return {
      contractAddress: address,
      txHash: receipt!.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${receipt!.hash}`,
    };
  }

  /**
   * Check if an address has contract code deployed.
   * @param address - address to check
   * @returns true if contract code exists
   */
  async isContract(address: string): Promise<boolean> {
    const code = await this.provider.getCode(address);
    return code !== '0x';
  }

  /**
   * Get the raw bytecode at an address.
   * @param address - contract address
   * @returns hex-encoded bytecode or "0x" if no contract
   */
  async getCode(address: string): Promise<string> {
    return this.provider.getCode(address);
  }

  /**
   * Submit contract source code for verification on the QFC explorer.
   * The explorer compiles the source, strips metadata, and compares against deployed bytecode.
   *
   * @param address - contract address to verify
   * @param sourceCode - Solidity source code
   * @param compilerVersion - e.g. "v0.8.28"
   * @param evmVersion - e.g. "paris" (required for QFC, no PUSH0)
   * @param optimizationRuns - optimizer runs (e.g. 200), omit for no optimization
   * @param constructorArgs - ABI-encoded constructor arguments (hex), optional
   */
  async verify(
    address: string,
    sourceCode: string,
    compilerVersion: string = 'v0.8.28',
    evmVersion: string = 'paris',
    optimizationRuns?: number,
    constructorArgs?: string,
  ): Promise<VerifyResult> {
    const explorerUrl = this.networkConfig.explorerUrl;
    const response = await fetch(`${explorerUrl}/api/contracts/verify`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        address,
        sourceCode,
        compilerVersion,
        evmVersion,
        optimizationRuns,
        constructorArgs,
      }),
    });

    const data = await response.json();

    if (!data.ok) {
      throw new Error(data.error || 'Verification failed');
    }

    return {
      address: data.data.address,
      verified: data.data.verified,
      contractName: data.data.contractName,
      compiler: data.data.compiler,
      evmVersion: data.data.evmVersion,
    };
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig } from './provider.js';
import { QFCFaucet } from './faucet.js';
import { QFCChain } from './chain.js';
import { QFCToken } from './token.js';
import { QFCMinerMonitor } from './miner-monitor.js';

export interface BotCommand {
  command: string;
  args: string[];
}

export interface BotResponse {
  success: boolean;
  message: string;
}

/**
 * QFCDiscordBot — command processor for Discord bot integration.
 *
 * Framework-agnostic: parses command strings and returns formatted responses.
 * Does NOT depend on discord.js — can be used with any Discord bot framework.
 */
export class QFCDiscordBot {
  private network: NetworkName;
  private provider;
  private networkConfig;
  private faucet: QFCFaucet | null;
  private chain: QFCChain;
  private token: QFCToken;
  private minerMonitor: QFCMinerMonitor;

  constructor(network: NetworkName = 'testnet') {
    this.network = network;
    this.networkConfig = getNetworkConfig(network);
    this.provider = createProvider(network);
    this.chain = new QFCChain(network);
    this.token = new QFCToken(network);
    this.minerMonitor = new QFCMinerMonitor(network);
    // Faucet is only available on testnet
    this.faucet = network === 'testnet' ? new QFCFaucet(network) : null;
  }

  /** Parse a raw message like "!faucet 0x1234..." into a BotCommand */
  parseCommand(message: string, prefix: string = '!'): BotCommand | null {
    const trimmed = message.trim();
    if (!trimmed.startsWith(prefix)) return null;

    const withoutPrefix = trimmed.slice(prefix.length);
    const parts = withoutPrefix.split(/\s+/).filter((p) => p.length > 0);
    if (parts.length === 0) return null;

    return {
      command: parts[0].toLowerCase(),
      args: parts.slice(1),
    };
  }

  /** Execute a command and return a formatted response */
  async execute(cmd: BotCommand): Promise<BotResponse> {
    try {
      switch (cmd.command) {
        case 'help':
          return this.cmdHelp();
        case 'faucet':
          return await this.cmdFaucet(cmd.args);
        case 'balance':
          return await this.cmdBalance(cmd.args);
        case 'portfolio':
          return await this.cmdPortfolio(cmd.args);
        case 'tx':
          return await this.cmdTx(cmd.args);
        case 'block':
          return await this.cmdBlock(cmd.args);
        case 'price':
          return await this.cmdPrice();
        case 'miner':
          return await this.cmdMiner(cmd.args);
        case 'info':
          return await this.cmdInfo();
        default:
          return {
            success: false,
            message: `Unknown command \`${cmd.command}\`. Use \`!help\` for available commands.`,
          };
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      return { success: false, message: `**Error:** ${msg}` };
    }
  }

  /** Convenience: parse + execute in one call */
  async handleMessage(message: string, prefix: string = '!'): Promise<BotResponse | null> {
    const cmd = this.parseCommand(message, prefix);
    if (!cmd) return null;
    return this.execute(cmd);
  }

  // ── Command handlers ──────────────────────────────────────────────

  private cmdHelp(): BotResponse {
    const lines = [
      '**QFC Bot Commands**',
      '',
      '`!help` — Show this help message',
      '`!faucet <address>` — Request test QFC (testnet only)',
      '`!balance <address>` — Check QFC balance',
      '`!portfolio <address>` — Show token holdings',
      '`!tx <hash>` — Look up a transaction',
      '`!block [number|latest]` — Get block info',
      '`!price` — Show current gas price',
      '`!miner <address>` — Show miner earnings & status',
      '`!info` — Show network info',
    ];
    return { success: true, message: lines.join('\n') };
  }

  private async cmdFaucet(args: string[]): Promise<BotResponse> {
    if (!this.faucet) {
      return { success: false, message: '**Error:** Faucet is only available on testnet.' };
    }
    if (args.length === 0) {
      return { success: false, message: 'Usage: `!faucet <address>`' };
    }
    const address = args[0];
    if (!ethers.isAddress(address)) {
      return { success: false, message: '**Error:** Invalid address format. Expected `0x` + 40 hex characters.' };
    }

    const result = await this.faucet.requestQFC(address);
    return {
      success: true,
      message: [
        '**Faucet Request Sent**',
        `> **To:** \`${result.to}\``,
        `> **Amount:** ${result.amount} QFC`,
        `> **Tx:** [\`${result.txHash.slice(0, 18)}...\`](${result.explorerUrl})`,
      ].join('\n'),
    };
  }

  private async cmdBalance(args: string[]): Promise<BotResponse> {
    if (args.length === 0) {
      return { success: false, message: 'Usage: `!balance <address>`' };
    }
    const address = args[0];
    if (!ethers.isAddress(address)) {
      return { success: false, message: '**Error:** Invalid address format. Expected `0x` + 40 hex characters.' };
    }

    const balance = await this.provider.getBalance(address);
    const qfc = ethers.formatEther(balance);
    return {
      success: true,
      message: [
        '**QFC Balance**',
        `> **Address:** \`${address}\``,
        `> **Balance:** \`${qfc}\` QFC`,
      ].join('\n'),
    };
  }

  private async cmdPortfolio(args: string[]): Promise<BotResponse> {
    if (args.length === 0) {
      return { success: false, message: 'Usage: `!portfolio <address>`' };
    }
    const address = args[0];
    if (!ethers.isAddress(address)) {
      return { success: false, message: '**Error:** Invalid address format. Expected `0x` + 40 hex characters.' };
    }

    const portfolio = await this.token.getPortfolio(address);
    const lines = [
      `**Portfolio for** \`${address}\``,
      '',
      `**Native QFC:** \`${portfolio.nativeBalance}\` QFC`,
    ];

    if (portfolio.tokens.length > 0) {
      lines.push('', '**ERC-20 Tokens:**');
      for (const t of portfolio.tokens) {
        lines.push(`> **${t.symbol}** (\`${t.name}\`): \`${t.balance}\``);
      }
    } else {
      lines.push('', '*No ERC-20 token holdings found.*');
    }

    return { success: true, message: lines.join('\n') };
  }

  private async cmdTx(args: string[]): Promise<BotResponse> {
    if (args.length === 0) {
      return { success: false, message: 'Usage: `!tx <hash>`' };
    }
    const hash = args[0];

    const tx = await this.chain.getTransaction(hash);
    if (!tx) {
      return { success: false, message: `**Error:** Transaction \`${hash}\` not found.` };
    }

    const explorerUrl = `${this.networkConfig.explorerUrl}/txs/${tx.hash}`;
    return {
      success: true,
      message: [
        '**Transaction Details**',
        `> **Hash:** [\`${tx.hash.slice(0, 18)}...\`](${explorerUrl})`,
        `> **From:** \`${tx.from}\``,
        `> **To:** \`${tx.to ?? 'Contract Creation'}\``,
        `> **Value:** \`${tx.value}\` QFC`,
        `> **Gas Price:** \`${tx.gasPrice}\` gwei`,
        `> **Status:** ${tx.status === 'confirmed' ? '**Confirmed** (block `' + tx.blockNumber + '`)' : '**Pending**'}`,
      ].join('\n'),
    };
  }

  private async cmdBlock(args: string[]): Promise<BotResponse> {
    const blockArg = args.length === 0 ? 'latest' : args[0];
    const blockTag: number | 'latest' =
      blockArg === 'latest' ? 'latest' : parseInt(blockArg, 10);

    if (typeof blockTag === 'number' && isNaN(blockTag)) {
      return { success: false, message: 'Usage: `!block [number|latest]`' };
    }

    const block = await this.chain.getBlock(blockTag);
    const date = new Date(block.timestamp * 1000).toUTCString();
    return {
      success: true,
      message: [
        '**Block Info**',
        `> **Number:** \`${block.number}\``,
        `> **Hash:** \`${block.hash.slice(0, 18)}...\``,
        `> **Time:** ${date}`,
        `> **Miner:** \`${block.miner}\``,
        `> **Transactions:** ${block.transactionCount}`,
        `> **Gas Used:** ${block.gasUsed.toLocaleString()} / ${block.gasLimit.toLocaleString()}`,
      ].join('\n'),
    };
  }

  private async cmdPrice(): Promise<BotResponse> {
    const feeData = await this.provider.getFeeData();
    const gasPrice = feeData.gasPrice
      ? ethers.formatUnits(feeData.gasPrice, 'gwei')
      : 'unknown';
    return {
      success: true,
      message: [
        '**Gas Price**',
        `> **Current:** \`${gasPrice}\` gwei`,
      ].join('\n'),
    };
  }

  private async cmdMiner(args: string[]): Promise<BotResponse> {
    if (args.length === 0) {
      return { success: false, message: 'Usage: `!miner <address>`' };
    }
    const address = args[0];
    if (!ethers.isAddress(address)) {
      return { success: false, message: '**Error:** Invalid address format. Expected `0x` + 40 hex characters.' };
    }

    const status = await this.minerMonitor.getStatus(address);
    const recentEarnings = await this.minerMonitor.getRecentEarnings(address);
    const minerUrl = `${this.networkConfig.explorerUrl}/miner/${address}`;

    const lines = [
      '**⛏️ Miner Status**',
      `> **Address:** [\`${address.slice(0, 10)}...${address.slice(-8)}\`](${minerUrl})`,
      `> **Total Earned:** \`${status.totalEarnedQfc}\` QFC`,
      `> **Available:** \`${ethers.formatEther(BigInt(status.available))}\` QFC`,
      `> **Locked:** \`${ethers.formatEther(BigInt(status.locked))}\` QFC`,
      `> **Score:** ${status.contributionScore}/100`,
      `> **Vesting Tranches:** ${status.activeTranches}`,
    ];

    if (recentEarnings.length > 0) {
      lines.push('', '**Recent Earnings:**');
      for (const e of recentEarnings.slice(0, 5)) {
        lines.push(`> \`${e.rewardQfc}\` QFC — ${e.taskType} (block ${e.blockHeight})`);
      }
      if (recentEarnings.length > 5) {
        lines.push(`> *...and ${recentEarnings.length - 5} more*`);
      }
    }

    return { success: true, message: lines.join('\n') };
  }

  private async cmdInfo(): Promise<BotResponse> {
    const [blockNumber, feeData] = await Promise.all([
      this.provider.getBlockNumber(),
      this.provider.getFeeData(),
    ]);
    const gasPrice = feeData.gasPrice
      ? ethers.formatUnits(feeData.gasPrice, 'gwei')
      : 'unknown';

    return {
      success: true,
      message: [
        '**QFC Network Info**',
        `> **Network:** ${this.networkConfig.name}`,
        `> **Chain ID:** \`${this.networkConfig.chainId}\``,
        `> **Latest Block:** \`${blockNumber}\``,
        `> **Gas Price:** \`${gasPrice}\` gwei`,
        `> **Explorer:** ${this.networkConfig.explorerUrl}`,
        `> **RPC:** \`${this.networkConfig.rpcUrl}\``,
      ].join('\n'),
    };
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, rpcCall } from './provider.js';

export interface EpochInfo {
  number: number;
  startTime: number;
  durationMs: number;
}

/**
 * QFCEpoch — epoch and finality information.
 */
export class QFCEpoch {
  private provider: ethers.JsonRpcProvider;

  constructor(network: NetworkName = 'testnet') {
    this.provider = createProvider(network);
  }

  /** Get current epoch info */
  async getCurrentEpoch(): Promise<EpochInfo> {
    const raw = await rpcCall(this.provider, 'qfc_getEpoch', []);
    return {
      number: Number(raw.number),
      startTime: Number(raw.startTime),
      durationMs: Number(raw.durationMs),
    };
  }

  /** Get the latest finalized block number */
  async getFinalizedBlock(): Promise<number> {
    const raw = await rpcCall(this.provider, 'qfc_getFinalizedBlock', []);
    return Number(raw);
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider } from './provider.js';

export interface EventSubscription {
  stop: () => void;
}

export interface TransferEvent {
  blockNumber: number;
  txHash: string;
  from: string;
  to: string;
  value: string;
}

export interface SwapEvent {
  blockNumber: number;
  txHash: string;
  user: string;
  tokenIn: string;
  amountIn: string;
  tokenOut: string;
  amountOut: string;
}

export interface BlockEvent {
  number: number;
  hash: string;
  timestamp: number;
  transactions: number;
}

/**
 * QFCEvents — Watch for on-chain events via polling.
 * QFC doesn't support WebSocket subscriptions, so we poll for new blocks/logs.
 */
export class QFCEvents {
  private provider: ethers.JsonRpcProvider;

  constructor(network: NetworkName = 'testnet') {
    this.provider = createProvider(network);
  }

  /**
   * Watch ERC-20 Transfer events for a token.
   * @param tokenAddress - ERC-20 token contract
   * @param callback - called for each new Transfer event
   * @param intervalMs - polling interval (default 5000ms)
   */
  watchTransfers(
    tokenAddress: string,
    callback: (event: TransferEvent) => void,
    intervalMs: number = 5000,
  ): EventSubscription {
    const transferTopic = ethers.id('Transfer(address,address,uint256)');
    let lastBlock = 0;
    let stopped = false;

    const poll = async () => {
      while (!stopped) {
        try {
          const currentBlock = await this.provider.getBlockNumber();
          if (lastBlock === 0) {
            lastBlock = currentBlock;
            await new Promise((r) => setTimeout(r, intervalMs));
            continue;
          }

          if (currentBlock > lastBlock) {
            const logs = await this.provider.send('eth_getLogs', [{
              address: tokenAddress,
              topics: [transferTopic],
              fromBlock: `0x${(lastBlock + 1).toString(16)}`,
              toBlock: `0x${currentBlock.toString(16)}`,
            }]);

            for (const log of logs) {
              const from = '0x' + log.topics[1].slice(26);
              const to = '0x' + log.topics[2].slice(26);
              const value = BigInt(log.data).toString();
              callback({
                blockNumber: parseInt(log.blockNumber, 16),
                txHash: log.transactionHash,
                from,
                to,
                value,
              });
            }
            lastBlock = currentBlock;
          }
        } catch {
          // Ignore polling errors, retry next interval
        }
        await new Promise((r) => setTimeout(r, intervalMs));
      }
    };

    poll();
    return { stop: () => { stopped = true; } };
  }

  /**
   * Watch Swap events on an AMM pool.
   * @param poolAddress - SimpleSwap pool contract
   * @param callback - called for each new Swap event
   * @param intervalMs - polling interval (default 5000ms)
   */
  watchSwaps(
    poolAddress: string,
    callback: (event: SwapEvent) => void,
    intervalMs: number = 5000,
  ): EventSubscription {
    const swapTopic = ethers.id('Swap(address,address,uint256,address,uint256)');
    let lastBlock = 0;
    let stopped = false;

    const poll = async () => {
      while (!stopped) {
        try {
          const currentBlock = await this.provider.getBlockNumber();
          if (lastBlock === 0) {
            lastBlock = currentBlock;
            await new Promise((r) => setTimeout(r, intervalMs));
            continue;
          }

          if (currentBlock > lastBlock) {
            const logs = await this.provider.send('eth_getLogs', [{
              address: poolAddress,
              topics: [swapTopic],
              fromBlock: `0x${(lastBlock + 1).toString(16)}`,
              toBlock: `0x${currentBlock.toString(16)}`,
            }]);

            for (const log of logs) {
              const user = '0x' + log.topics[1].slice(26);
              const iface = new ethers.Interface([
                'event Swap(address indexed user, address tokenIn, uint256 amountIn, address tokenOut, uint256 amountOut)',
              ]);
              const decoded = iface.decodeEventLog('Swap', log.data, log.topics);
              callback({
                blockNumber: parseInt(log.blockNumber, 16),
                txHash: log.transactionHash,
                user,
                tokenIn: decoded.tokenIn,
                amountIn: decoded.amountIn.toString(),
                tokenOut: decoded.tokenOut,
                amountOut: decoded.amountOut.toString(),
              });
            }
            lastBlock = currentBlock;
          }
        } catch {
          // Ignore polling errors
        }
        await new Promise((r) => setTimeout(r, intervalMs));
      }
    };

    poll();
    return { stop: () => { stopped = true; } };
  }

  /**
   * Watch for new blocks.
   * @param callback - called for each new block
   * @param intervalMs - polling interval (default 5000ms)
   */
  watchBlocks(
    callback: (event: BlockEvent) => void,
    intervalMs: number = 5000,
  ): EventSubscription {
    let lastBlock = 0;
    let stopped = false;

    const poll = async () => {
      while (!stopped) {
        try {
          const currentBlock = await this.provider.getBlockNumber();
          if (lastBlock === 0) {
            lastBlock = currentBlock - 1;
          }

          for (let i = lastBlock + 1; i <= currentBlock; i++) {
            const block = await this.provider.send('eth_getBlockByNumber', [
              `0x${i.toString(16)}`,
              false,
            ]);
            if (block) {
              callback({
                number: i,
                hash: block.hash,
                timestamp: parseInt(block.timestamp, 16),
                transactions: block.transactions?.length ?? 0,
              });
            }
          }
          lastBlock = currentBlock;
        } catch {
          // Ignore polling errors
        }
        await new Promise((r) => setTimeout(r, intervalMs));
      }
    };

    poll();
    return { stop: () => { stopped = true; } };
  }

  /**
   * Watch NFT marketplace sale events.
   * @param marketplaceAddress - NFTMarketplace contract
   * @param callback - called for each Sold event
   * @param intervalMs - polling interval (default 5000ms)
   */
  watchNFTSales(
    marketplaceAddress: string,
    callback: (event: { listingId: number; buyer: string; seller: string; price: string; blockNumber: number; txHash: string }) => void,
    intervalMs: number = 5000,
  ): EventSubscription {
    const soldTopic = ethers.id('Sold(uint256,address,address,uint256)');
    let lastBlock = 0;
    let stopped = false;

    const poll = async () => {
      while (!stopped) {
        try {
          const currentBlock = await this.provider.getBlockNumber();
          if (lastBlock === 0) {
            lastBlock = currentBlock;
            await new Promise((r) => setTimeout(r, intervalMs));
            continue;
          }

          if (currentBlock > lastBlock) {
            const logs = await this.provider.send('eth_getLogs', [{
              address: marketplaceAddress,
              topics: [soldTopic],
              fromBlock: `0x${(lastBlock + 1).toString(16)}`,
              toBlock: `0x${currentBlock.toString(16)}`,
            }]);

            for (const log of logs) {
              const listingId = Number(BigInt(log.topics[1]));
              const buyer = '0x' + log.topics[2].slice(26);
              const seller = '0x' + log.topics[3].slice(26);
              const price = ethers.formatEther(BigInt(log.data));
              callback({
                listingId,
                buyer,
                seller,
                price,
                blockNumber: parseInt(log.blockNumber, 16),
                txHash: log.transactionHash,
              });
            }
            lastBlock = currentBlock;
          }
        } catch {
          // Ignore polling errors
        }
        await new Promise((r) => setTimeout(r, intervalMs));
      }
    };

    poll();
    return { stop: () => { stopped = true; } };
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig, rpcCall } from './provider.js';

export interface FaucetResult {
  txHash: string;
  amount: string;
  to: string;
  explorerUrl: string;
}

/**
 * QFCFaucet — request test tokens on QFC testnet.
 */
export class QFCFaucet {
  private provider: ethers.JsonRpcProvider;
  private networkConfig;

  constructor(network: NetworkName = 'testnet') {
    if (network !== 'testnet') {
      throw new Error('Faucet is only available on testnet (chain_id=9000)');
    }
    this.provider = createProvider(network);
    this.networkConfig = getNetworkConfig(network);
  }

  /**
   * Request test QFC tokens.
   * @param address - recipient address
   * @param amount - amount in QFC (not wei), defaults to "10"
   */
  async requestQFC(address: string, amount: string = '10'): Promise<FaucetResult> {
    if (!ethers.isAddress(address)) {
      throw new Error('Invalid address format. Expected 0x + 40 hex characters.');
    }
    const parsed = parseFloat(amount);
    if (isNaN(parsed) || parsed <= 0) {
      throw new Error('Amount must be a positive number.');
    }

    let result: any;
    try {
      const amountInWei = ethers.parseEther(amount).toString();
      result = await rpcCall(this.provider, 'qfc_requestFaucet', [address, amountInWei]);
    } catch (err: any) {
      throw new Error(`Faucet request failed: ${err.message ?? err}`);
    }

    const txHash = typeof result === 'string' ? result : result.txHash;
    return {
      txHash,
      amount,
      to: address,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${txHash}`,
    };
  }
}

