/**
 * QFCInference — submit and query AI inference tasks on QFC.
 */
export class QFCInference {
  private provider: ethers.JsonRpcProvider;

  constructor(network: NetworkName = 'testnet') {
    this.provider = createProvider(network);
  }

  /** List approved models */
  async getModels(): Promise<InferenceModel[]> {
    return rpcCall(this.provider, 'qfc_getSupportedModels', []);
  }

  /** Get inference statistics (tasks completed, avg time, FLOPS, pass rate) */
  async getStats(): Promise<{
    tasksCompleted: number;
    avgTimeMs: number;
    flopsTotal: string;
    passRate: number;
  }> {
    const r = await rpcCall(this.provider, 'qfc_getInferenceStats', []);
    return {
      tasksCompleted: Number(r.tasksCompleted),
      avgTimeMs: Number(r.avgTimeMs),
      flopsTotal: String(r.flopsTotal),
      passRate: Number(r.passRate),
    };
  }

  /** Query the status of a submitted inference task */
  async getTaskStatus(taskId: string): Promise<InferenceTaskStatus> {
    try {
      return await rpcCall(this.provider, 'qfc_getPublicTaskStatus', [taskId]);
    } catch (err: any) {
      if (typeof err?.message === 'string' && err.message.includes('Task not found')) {
        return {
          taskId,
          status: 'NotFound',
          submitter: '',
          taskType: '',
          modelId: '',
          createdAt: 0,
          deadline: 0,
          maxFee: '0',
        } as InferenceTaskStatus;
      }
      throw err;
    }
  }

  /**
   * Poll until the task reaches a terminal state.
   * @param taskId - Task ID (hex)
   * @param timeoutMs - Max wait (default 120s)
   * @param intervalMs - Poll interval (default 2s)
   */
  async waitForResult(
    taskId: string,
    timeoutMs: number = 120_000,
    intervalMs: number = 2_000,
  ): Promise<InferenceTaskStatus> {
    const deadline = Date.now() + timeoutMs;
    let sawInProgress = false;
    while (Date.now() < deadline) {
      const status = await this.getTaskStatus(taskId);
      if (status.status === 'Pending' || status.status === 'Assigned') {
        sawInProgress = true;
      }
      if (status.status === 'Completed' || status.status === 'Failed' || status.status === 'Expired') {
        return status;
      }
      // qfc-core #69: completed/expired/failed tasks are deleted from TaskPool,
      // so getTaskStatus returns NotFound. If we previously saw the task in progress,
      // treat this as Expired rather than an error.
      if (status.status === 'NotFound' && sawInProgress) {
        return {
          ...status,
          status: 'Expired',
          result: undefined,
          resultType: undefined,
          _note: 'Task disappeared from TaskPool after being in progress (qfc-core #69). Likely Expired.',
        } as InferenceTaskStatus & { _note: string };
      }
      if (status.status === 'NotFound') {
        return status;
      }
      await new Promise((r) => setTimeout(r, intervalMs));
    }
    return this.getTaskStatus(taskId);
  }

  /**
   * Submit a public inference task.
   * @param modelId - model ID from the registry (e.g. "qfc-embed-small")
   * @param taskType - task type (e.g. "TextEmbedding", "TextGeneration")
   * @param input - input data (text string — will be base64-encoded automatically)
   * @param maxFee - maximum fee in QFC (e.g. "0.5")
   * @param signer - wallet to sign and pay for the task
   */
  async submitTask(
    modelId: string,
    taskType: string,
    input: string,
    maxFee: string,
    signer: ethers.Wallet,
  ): Promise<string> {
    const inputData = Buffer.from(input).toString('base64');
    const payload = {
      modelId,
      taskType,
      inputData,
      maxFee: ethers.parseEther(maxFee).toString(),
      submitter: signer.address,
    };
    const message = JSON.stringify(payload);
    const signature = await signer.signMessage(message);
    const result = await rpcCall(this.provider, 'qfc_submitPublicTask', [
      { ...payload, signature },
    ]);
    return typeof result === 'string' ? result : result.taskId;
  }

  /** Estimate the fee for an inference task */
  async estimateFee(modelId: string, taskType: string = 'TextEmbedding', inputSize: number = 0): Promise<FeeEstimate> {
    const raw = await rpcCall(this.provider, 'qfc_estimateInferenceFee', [
      { modelId, taskType, inputSize },
    ]);
    return {
      baseFee: ethers.formatEther(BigInt(raw.baseFee)),
      model: raw.modelId,
      gpuTier: raw.gpuTier,
      estimatedTimeMs: Number(raw.estimatedTimeMs),
    };
  }

  /**
   * Fetch the full IPFS result for a given CID via the node's gateway proxy.
   * Calls `qfc_getInferenceResult` and returns the base64-encoded content.
   *
   * @param cid - IPFS content identifier (e.g. "QmXYZ...")
   * @returns Base64-encoded result payload
   */
  async fetchIpfsResult(cid: string): Promise<string> {
    return rpcCall(this.provider, 'qfc_getInferenceResult', [cid]);
  }

  /**
   * Unified method to retrieve the result of a completed inference task,
   * regardless of whether it was stored inline or on IPFS.
   *
   * - If `resultType` is `'inline'`, returns the `result` field directly.
   * - If `resultType` is `'ipfs'`, fetches the full content via `fetchIpfsResult`.
   * - For legacy responses without `resultType`, falls back to `result`.
   *
   * @param taskId - Task ID (hex)
   * @returns Base64-encoded result string
   * @throws If the task has no result or is not completed
   */
  async getResult(taskId: string): Promise<string> {
    const status = await this.getTaskStatus(taskId);
    if (status.status !== 'Completed') {
      throw new Error(`Task ${taskId} is not completed (status: ${status.status})`);
    }

    if (status.resultType === 'ipfs') {
      if (!status.resultCid) {
        throw new Error(`Task ${taskId} has resultType 'ipfs' but no resultCid`);
      }
      return this.fetchIpfsResult(status.resultCid);
    }

    // inline or legacy (no resultType field)
    if (!status.result) {
      throw new Error(`Task ${taskId} is completed but has no result`);
    }
    return status.result;
  }

  /**
   * Decode a base64 result payload from a completed task.
   * Works with both inline and IPFS-fetched results — both are base64-encoded
   * JSON envelopes with the same structure.
   */
  decodeResult(base64Result: string): DecodedResult {
    const json = Buffer.from(base64Result, 'base64').toString('utf-8');
    const envelope = JSON.parse(json);
    const outputRaw = Buffer.from(envelope.output_base64, 'base64').toString('utf-8');
    let output: any;
    try {
      output = JSON.parse(outputRaw);
    } catch {
      output = outputRaw;
    }
    return {
      model: envelope.model,
      submitter: envelope.submitter,
      miner: envelope.miner,
      output,
      executionTimeMs: envelope.execution_time_ms,
      timestamps: {
        submitted: envelope.submitted_at,
        completed: envelope.completed_at,
      },
    };
  }

  /**
   * Decode a base64 result payload to raw bytes.
   */
  decodeResultBytes(base64Result: string): Uint8Array {
    return Buffer.from(base64Result, 'base64');
  }
}

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { ethers } from 'ethers';
import type { NetworkName } from './provider.js';

export interface WalletMeta {
  address: string;
  name: string;
  network: NetworkName;
  createdAt: string;
}

export class QFCKeystore {
  private storeDir: string;
  private keystoreDir: string;
  private metaPath: string;

  constructor(storeDir?: string) {
    this.storeDir = storeDir ?? path.join(os.homedir(), '.openclaw', 'qfc-wallets');
    this.keystoreDir = path.join(this.storeDir, 'keystore');
    this.metaPath = path.join(this.storeDir, 'meta.json');
  }

  private ensureDir(): void {
    fs.mkdirSync(this.keystoreDir, { recursive: true });
  }

  private readMeta(): WalletMeta[] {
    if (!fs.existsSync(this.metaPath)) return [];
    const raw = fs.readFileSync(this.metaPath, 'utf-8');
    return JSON.parse(raw) as WalletMeta[];
  }

  private writeMeta(meta: WalletMeta[]): void {
    this.ensureDir();
    fs.writeFileSync(this.metaPath, JSON.stringify(meta, null, 2), 'utf-8');
    fs.chmodSync(this.metaPath, 0o600);
  }

  async saveWallet(
    wallet: ethers.Wallet,
    password: string,
    opts?: { name?: string; network?: NetworkName },
  ): Promise<string> {
    this.ensureDir();

    const address = wallet.address.toLowerCase();
    const keystorePath = path.join(this.keystoreDir, `${address}.json`);

    const json = await wallet.encrypt(password);
    fs.writeFileSync(keystorePath, json, 'utf-8');
    fs.chmodSync(keystorePath, 0o600);

    const meta = this.readMeta();
    const existing = meta.findIndex((m) => m.address === address);
    const entry: WalletMeta = {
      address,
      name: opts?.name ?? 'default',
      network: opts?.network ?? 'testnet',
      createdAt: new Date().toISOString(),
    };

    if (existing >= 0) {
      meta[existing] = entry;
    } else {
      meta.push(entry);
    }
    this.writeMeta(meta);

    return keystorePath;
  }

  async loadWallet(address: string, password: string): Promise<ethers.Wallet> {
    const normalised = address.toLowerCase();
    const keystorePath = path.join(this.keystoreDir, `${normalised}.json`);

    if (!fs.existsSync(keystorePath)) {
      throw new Error(`No keystore found for ${address}`);
    }

    const json = fs.readFileSync(keystorePath, 'utf-8');
    return ethers.Wallet.fromEncryptedJson(json, password) as Promise<ethers.Wallet>;
  }

  listWallets(): WalletMeta[] {
    return this.readMeta();
  }

  removeWallet(address: string): boolean {
    const normalised = address.toLowerCase();
    const keystorePath = path.join(this.keystoreDir, `${normalised}.json`);

    const meta = this.readMeta();
    const filtered = meta.filter((m) => m.address !== normalised);
    if (filtered.length === meta.length) return false;

    this.writeMeta(filtered);
    if (fs.existsSync(keystorePath)) {
      fs.unlinkSync(keystorePath);
    }
    return true;
  }

  getKeystoreJson(address: string): string | null {
    const normalised = address.toLowerCase();
    const keystorePath = path.join(this.keystoreDir, `${normalised}.json`);

    if (!fs.existsSync(keystorePath)) return null;
    const raw = fs.readFileSync(keystorePath, 'utf-8');
    const parsed = JSON.parse(raw);
    if (parsed.Crypto && !parsed.crypto) {
      parsed.crypto = parsed.Crypto;
      delete parsed.Crypto;
    }
    return JSON.stringify(parsed);
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig } from './provider.js';

const MARKETPLACE_ABI = [
  'constructor(uint256 feeBps, address feeRecipient)',
  'function list(address nftContract, uint256 tokenId, uint256 price) returns (uint256 listingId)',
  'function buy(uint256 listingId) payable',
  'function cancel(uint256 listingId)',
  'function getListing(uint256 listingId) view returns (address seller, address nftContract, uint256 tokenId, uint256 price, bool active)',
  'function getActiveListingCount() view returns (uint256)',
  'function nextListingId() view returns (uint256)',
  'function owner() view returns (address)',
  'function feeRecipient() view returns (address)',
  'function feeBps() view returns (uint256)',
  'function setFee(uint256 feeBps, address feeRecipient)',
  'event Listed(uint256 indexed listingId, address indexed seller, address nftContract, uint256 tokenId, uint256 price)',
  'event Sold(uint256 indexed listingId, address indexed buyer, address indexed seller, uint256 price)',
  'event Cancelled(uint256 indexed listingId)',
  'event FeeUpdated(uint256 newFeeBps, address newFeeRecipient)',
];

const ERC721_APPROVE_ABI = [
  'function approve(address to, uint256 tokenId)',
  'function setApprovalForAll(address operator, bool approved)',
  'function getApproved(uint256 tokenId) view returns (address)',
  'function isApprovedForAll(address owner, address operator) view returns (bool)',
  'function ownerOf(uint256 tokenId) view returns (address)',
];

/**
 * Pre-compiled NFTMarketplace bytecode (Solidity 0.8.34, evmVersion: paris, optimizer: 200 runs).
 * Constructor: (uint256 feeBps, address feeRecipient)
 * feeBps: platform fee in basis points (200 = 2%, max 1000 = 10%)
 * feeRecipient: address that receives fees (address(0) defaults to deployer)
 */
const MARKETPLACE_DEPLOY_BYTECODE = '';

/**
 * Solidity source code for the NFTMarketplace contract.
 */
export const MARKETPLACE_SOURCE_CODE = `// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC721 {
    function ownerOf(uint256 tokenId) external view returns (address);
    function transferFrom(address from, address to, uint256 tokenId) external;
    function getApproved(uint256 tokenId) external view returns (address);
    function isApprovedForAll(address owner, address operator) external view returns (bool);
}

contract NFTMarketplace {
    struct Listing {
        address seller;
        address nftContract;
        uint256 tokenId;
        uint256 price;
        bool active;
    }

    uint256 public nextListingId;
    mapping(uint256 => Listing) public listings;

    address public owner;
    address public feeRecipient;
    uint256 public feeBps; // basis points (200 = 2%, max 1000 = 10%)

    event Listed(uint256 indexed listingId, address indexed seller, address nftContract, uint256 tokenId, uint256 price);
    event Sold(uint256 indexed listingId, address indexed buyer, address indexed seller, uint256 price);
    event Cancelled(uint256 indexed listingId);
    event FeeUpdated(uint256 newFeeBps, address newFeeRecipient);

    constructor(uint256 _feeBps, address _feeRecipient) {
        require(_feeBps <= 1000, "fee too high");
        owner = msg.sender;
        feeBps = _feeBps;
        feeRecipient = _feeRecipient == address(0) ? msg.sender : _feeRecipient;
    }

    modifier onlyOwner() { require(msg.sender == owner, "not owner"); _; }

    function setFee(uint256 _feeBps, address _feeRecipient) external onlyOwner {
        require(_feeBps <= 1000, "fee too high");
        feeBps = _feeBps;
        if (_feeRecipient != address(0)) feeRecipient = _feeRecipient;
        emit FeeUpdated(_feeBps, feeRecipient);
    }

    function list(address nftContract, uint256 tokenId, uint256 price) external returns (uint256 listingId) {
        require(price > 0, "zero price");
        IERC721 nft = IERC721(nftContract);
        require(nft.ownerOf(tokenId) == msg.sender, "not owner");
        require(
            nft.getApproved(tokenId) == address(this) || nft.isApprovedForAll(msg.sender, address(this)),
            "not approved"
        );
        listingId = nextListingId++;
        listings[listingId] = Listing(msg.sender, nftContract, tokenId, price, true);
        emit Listed(listingId, msg.sender, nftContract, tokenId, price);
    }

    function buy(uint256 listingId) external payable {
        Listing storage l = listings[listingId];
        require(l.active, "not active");
        require(msg.value >= l.price, "insufficient payment");
        l.active = false;
        IERC721(l.nftContract).transferFrom(l.seller, msg.sender, l.tokenId);
        uint256 fee = (l.price * feeBps) / 10000;
        uint256 sellerAmount = l.price - fee;
        (bool ok, ) = l.seller.call{value: sellerAmount}("");
        require(ok, "seller payment failed");
        if (fee > 0) {
            (bool feeOk, ) = feeRecipient.call{value: fee}("");
            require(feeOk, "fee payment failed");
        }
        if (msg.value > l.price) {
            (bool refundOk, ) = msg.sender.call{value: msg.value - l.price}("");
            require(refundOk, "refund failed");
        }
        emit Sold(listingId, msg.sender, l.seller, l.price);
    }

    function cancel(uint256 listingId) external {
        Listing storage l = listings[listingId];
        require(l.active, "not active");
        require(l.seller == msg.sender, "not seller");
        l.active = false;
        emit Cancelled(listingId);
    }

    function getListing(uint256 listingId) external view returns (
        address seller, address nftContract, uint256 tokenId, uint256 price, bool active
    ) {
        Listing storage l = listings[listingId];
        return (l.seller, l.nftContract, l.tokenId, l.price, l.active);
    }

    function getActiveListingCount() external view returns (uint256 count) {
        for (uint256 i = 0; i < nextListingId; i++) {
            if (listings[i].active) count++;
        }
    }
}
`;

