/**
 * QFCMarketplace — Simple NFT marketplace on QFC.
 * List, buy, and cancel NFT listings. Payment in native QFC.
 */
export class QFCMarketplace {
  private provider: ethers.JsonRpcProvider;
  private networkConfig;

  constructor(network: NetworkName = 'testnet') {
    this.networkConfig = getNetworkConfig(network);
    this.provider = createProvider(network);
  }

  private async waitForReceipt(
    txHash: string,
    timeoutMs: number = 120_000,
  ): Promise<{ status: string; contractAddress: string; blockNumber: string; gasUsed: string; logs: Array<{ topics: string[]; data: string }> }> {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, 3000));
      const raw = await this.provider.send('eth_getTransactionReceipt', [txHash]);
      if (raw) return raw;
    }
    throw new Error(`Transaction ${txHash} not confirmed after ${timeoutMs / 1000}s`);
  }

  /**
   * Deploy a new NFT marketplace contract with configurable platform fee.
   * @param signer - wallet to deploy from (becomes owner)
   * @param feeBps - platform fee in basis points (default 200 = 2%, max 1000 = 10%, 0 = no fee)
   * @param feeRecipient - address that receives fees (default: deployer address)
   */
  async deploy(
    signer: ethers.Wallet,
    feeBps: number = 200,
    feeRecipient?: string,
  ): Promise<MarketplaceDeployResult> {
    const connected = signer.connect(this.provider);
    const factory = new ethers.ContractFactory(MARKETPLACE_ABI, MARKETPLACE_DEPLOY_BYTECODE, connected);
    const deployTx = await factory.getDeployTransaction(
      feeBps,
      feeRecipient ?? ethers.ZeroAddress,
    );
    deployTx.gasLimit = 1_500_000n;

    const tx = await connected.sendTransaction(deployTx);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`Marketplace deployment reverted (tx: ${tx.hash})`);
    }

    // Best-effort verification
    try {
      const constructorArgs = ethers.AbiCoder.defaultAbiCoder()
        .encode(['uint256', 'address'], [feeBps, feeRecipient ?? ethers.ZeroAddress])
        .slice(2);
      const verifyUrl = `${this.networkConfig.explorerUrl}/api/contracts/verify`;
      await fetch(verifyUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          address: receipt.contractAddress,
          sourceCode: MARKETPLACE_SOURCE_CODE,
          compilerVersion: 'v0.8.34+commit.1c8745a5',
          evmVersion: 'paris',
          optimizationRuns: 200,
          constructorArgs,
        }),
      });
    } catch {
      // Explorer unavailable
    }

    return {
      marketplaceAddress: receipt.contractAddress,
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/contract/${receipt.contractAddress}`,
    };
  }

  /**
   * List an NFT for sale. Auto-approves the marketplace if needed.
   * @param marketplace - marketplace contract address
   * @param nftContract - ERC-721 contract address
   * @param tokenId - token ID to list
   * @param priceQFC - price in native QFC (human-readable, e.g. "5.0")
   * @param signer - NFT owner
   */
  async listNFT(
    marketplace: string,
    nftContract: string,
    tokenId: number,
    priceQFC: string,
    signer: ethers.Wallet,
  ): Promise<ListNFTResult> {
    const connected = signer.connect(this.provider);
    const nft = new ethers.Contract(nftContract, ERC721_APPROVE_ABI, connected);

    // Auto-approve marketplace if not already
    const approved = await nft.getApproved(tokenId);
    const approvedForAll = await nft.isApprovedForAll(connected.address, marketplace);
    if (approved.toLowerCase() !== marketplace.toLowerCase() && !approvedForAll) {
      const approveTx = await nft.approve(marketplace, tokenId);
      const approveReceipt = await this.waitForReceipt(approveTx.hash);
      if (approveReceipt.status !== '0x1') {
        throw new Error(`NFT approval failed (tx: ${approveTx.hash})`);
      }
    }

    const price = ethers.parseEther(priceQFC);
    const mp = new ethers.Contract(marketplace, MARKETPLACE_ABI, connected);
    const txData = await mp.list.populateTransaction(nftContract, tokenId, price);
    txData.gasLimit = 300_000n;
    const tx = await connected.sendTransaction(txData);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`Listing failed (tx: ${tx.hash})`);
    }

    // Parse listing ID from event logs
    const listedTopic = ethers.id('Listed(uint256,address,address,uint256,uint256)');
    const log = receipt.logs?.find((l: { topics: string[] }) => l.topics[0] === listedTopic);
    const listingId = log ? BigInt(log.topics[1]).toString() : '0';

    return {
      listingId,
      nftContract,
      tokenId,
      price: priceQFC,
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${tx.hash}`,
    };
  }

  /**
   * Buy a listed NFT. Sends native QFC as payment.
   */
  async buyNFT(
    marketplace: string,
    listingId: number,
    signer: ethers.Wallet,
  ): Promise<BuyNFTResult> {
    const connected = signer.connect(this.provider);
    const mp = new ethers.Contract(marketplace, MARKETPLACE_ABI, this.provider);

    const [, , , price, active] = await mp.getListing(listingId);
    if (!active) throw new Error(`Listing ${listingId} is not active`);

    const mpConnected = new ethers.Contract(marketplace, MARKETPLACE_ABI, connected);
    const txData = await mpConnected.buy.populateTransaction(listingId);
    txData.value = price;
    txData.gasLimit = 300_000n;
    const tx = await connected.sendTransaction(txData);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`Purchase failed (tx: ${tx.hash})`);
    }

    return {
      listingId,
      price: ethers.formatEther(price),
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${tx.hash}`,
    };
  }

  /**
   * Cancel an active listing (seller only).
   */
  async cancelListing(
    marketplace: string,
    listingId: number,
    signer: ethers.Wallet,
  ): Promise<{ txHash: string; explorerUrl: string }> {
    const connected = signer.connect(this.provider);
    const mp = new ethers.Contract(marketplace, MARKETPLACE_ABI, connected);
    const txData = await mp.cancel.populateTransaction(listingId);
    txData.gasLimit = 100_000n;
    const tx = await connected.sendTransaction(txData);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`Cancel failed (tx: ${tx.hash})`);
    }

    return {
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${tx.hash}`,
    };
  }

  /**
   * Get a specific listing by ID.
   */
  async getListing(marketplace: string, listingId: number): Promise<ListingInfo> {
    const mp = new ethers.Contract(marketplace, MARKETPLACE_ABI, this.provider);
    const [seller, nftContract, tokenId, price, active] = await mp.getListing(listingId);
    return {
      listingId,
      seller,
      nftContract,
      tokenId: Number(tokenId),
      price: ethers.formatEther(price),
      active,
    };
  }

  /**
   * Get all active listings.
   */
  async getListings(marketplace: string): Promise<ListingInfo[]> {
    const mp = new ethers.Contract(marketplace, MARKETPLACE_ABI, this.provider);
    const nextId = await mp.nextListingId();
    const total = Number(nextId);
    const listings: ListingInfo[] = [];

    for (let i = 0; i < total; i++) {
      const [seller, nftContract, tokenId, price, active] = await mp.getListing(i);
      if (active) {
        listings.push({
          listingId: i,
          seller,
          nftContract,
          tokenId: Number(tokenId),
          price: ethers.formatEther(price),
          active: true,
        });
      }
    }

    return listings;
  }

  /**
   * Get active listings filtered by NFT collection.
   */
  async getListingsByCollection(marketplace: string, nftContract: string): Promise<ListingInfo[]> {
    const all = await this.getListings(marketplace);
    return all.filter((l) => l.nftContract.toLowerCase() === nftContract.toLowerCase());
  }

  /**
   * Get marketplace fee info.
   */
  async getFeeInfo(marketplace: string): Promise<{ feeBps: number; feePercent: string; feeRecipient: string; owner: string }> {
    const mp = new ethers.Contract(marketplace, MARKETPLACE_ABI, this.provider);
    const [feeBps, recipient, owner] = await Promise.all([
      mp.feeBps(),
      mp.feeRecipient(),
      mp.owner(),
    ]);
    return {
      feeBps: Number(feeBps),
      feePercent: `${Number(feeBps) / 100}%`,
      feeRecipient: recipient,
      owner,
    };
  }

  /**
   * Update marketplace fee (owner only).
   * @param marketplace - marketplace contract address
   * @param feeBps - new fee in basis points (max 1000 = 10%)
   * @param feeRecipient - new fee recipient (optional, pass undefined to keep current)
   * @param signer - marketplace owner wallet
   */
  async setFee(
    marketplace: string,
    feeBps: number,
    signer: ethers.Wallet,
    feeRecipient?: string,
  ): Promise<{ txHash: string; explorerUrl: string }> {
    const connected = signer.connect(this.provider);
    const mp = new ethers.Contract(marketplace, MARKETPLACE_ABI, connected);
    const txData = await mp.setFee.populateTransaction(feeBps, feeRecipient ?? ethers.ZeroAddress);
    txData.gasLimit = 100_000n;
    const tx = await connected.sendTransaction(txData);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`setFee failed (tx: ${tx.hash})`);
    }

    return {
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${tx.hash}`,
    };
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, rpcCall, getNetworkConfig } from './provider.js';
import type { EventSubscription } from './events.js';

export interface MinerEarning {
  /** Block height where the reward was issued */
  blockHeight: number;
  /** Task ID (hex) */
  taskId: string;
  /** Reward amount in wei */
  reward: string;
  /** Reward amount in QFC (human-readable) */
  rewardQfc: string;
  /** Task type (e.g. "TextEmbedding", "TextGeneration") */
  taskType: string;
  /** Model used */
  modelId: string;
  /** Execution time in ms */
  executionTimeMs: number;
  /** Block timestamp (unix seconds) */
  timestamp: number;
}

export interface MinerStatus {
  address: string;
  /** Total earned in wei (hex) */
  totalEarned: string;
  /** Total earned in QFC */
  totalEarnedQfc: string;
  /** Locked (vesting) in wei (hex) */
  locked: string;
  /** Available to withdraw in wei (hex) */
  available: string;
  /** Contribution score (0-100) */
  contributionScore: number;
  /** Number of active vesting tranches */
  activeTranches: number;
}

export interface MinerMonitorOptions {
  /** Polling interval in ms (default 15000 — one block time) */
  intervalMs?: number;
  /** Called on each new earning */
  onEarning?: (earning: MinerEarning) => void;
  /** Called on status change (balance change, score change) */
  onStatusChange?: (prev: MinerStatus, current: MinerStatus) => void;
  /** Called on errors (default: silent) */
  onError?: (error: Error) => void;
}

/**
 * QFCMinerMonitor — watch a miner's earnings in real-time via polling.
 *
 * Polls `qfc_getMinerEarnings` and `qfc_getMinerVesting` to detect new
 * rewards and balance changes, then fires callbacks.
 *
 * Usage:
 * ```ts
 * const monitor = new QFCMinerMonitor('testnet');
 * const sub = monitor.watch('0xMinerAddress', {
 *   onEarning: (e) => console.log(`Earned ${e.rewardQfc} QFC for ${e.taskType} task!`),
 *   onStatusChange: (prev, curr) => console.log(`Balance: ${curr.totalEarnedQfc} QFC`),
 * });
 * // later: sub.stop();
 * ```
 */
export class QFCMinerMonitor {
  private provider: ethers.JsonRpcProvider;
  private network: NetworkName;

  constructor(network: NetworkName = 'testnet') {
    this.network = network;
    this.provider = createProvider(network);
  }

  /**
   * Start watching a miner address for new earnings.
   * Returns a subscription that can be stopped.
   */
  watch(minerAddress: string, options: MinerMonitorOptions = {}): EventSubscription {
    const {
      intervalMs = 15_000,
      onEarning,
      onStatusChange,
      onError,
    } = options;

    let stopped = false;
    let lastStatus: MinerStatus | null = null;
    let knownEarningBlocks = new Set<string>();

    const poll = async () => {
      // Initialize: fetch current earnings to avoid replaying history
      try {
        const earnings = await this.getRecentEarnings(minerAddress);
        for (const e of earnings) {
          knownEarningBlocks.add(`${e.blockHeight}:${e.taskId}`);
        }
        lastStatus = await this.getStatus(minerAddress);
      } catch (err) {
        onError?.(err instanceof Error ? err : new Error(String(err)));
      }

      while (!stopped) {
        await new Promise((r) => setTimeout(r, intervalMs));
        if (stopped) break;

        try {
          // Check for new earnings
          if (onEarning) {
            const earnings = await this.getRecentEarnings(minerAddress);
            for (const e of earnings) {
              const key = `${e.blockHeight}:${e.taskId}`;
              if (!knownEarningBlocks.has(key)) {
                knownEarningBlocks.add(key);
                onEarning(e);
              }
            }
          }

          // Check for status changes
          const currentStatus = await this.getStatus(minerAddress);
          if (onStatusChange && lastStatus) {
            if (
              lastStatus.totalEarned !== currentStatus.totalEarned ||
              lastStatus.available !== currentStatus.available ||
              lastStatus.contributionScore !== currentStatus.contributionScore
            ) {
              onStatusChange(lastStatus, currentStatus);
            }
          }
          lastStatus = currentStatus;
        } catch (err) {
          onError?.(err instanceof Error ? err : new Error(String(err)));
        }
      }
    };

    poll();
    return { stop: () => { stopped = true; } };
  }

  /** Get miner's current status (balance, score, vesting) */
  async getStatus(minerAddress: string): Promise<MinerStatus> {
    const [vesting, contribution] = await Promise.all([
      rpcCall(this.provider, 'qfc_getMinerVesting', [minerAddress]).catch(() => null),
      rpcCall(this.provider, 'qfc_getContributionScore', [minerAddress]).catch(() => null),
    ]);

    const totalEarned = vesting?.totalEarned ?? '0x0';
    const locked = vesting?.locked ?? '0x0';
    const available = vesting?.available ?? '0x0';

    return {
      address: minerAddress.toLowerCase(),
      totalEarned,
      totalEarnedQfc: this.formatWei(totalEarned),
      locked,
      available,
      contributionScore: Number(contribution?.score ?? 0),
      activeTranches: Number(vesting?.activeTranches ?? 0),
    };
  }

  /** Get recent earnings for a miner */
  async getRecentEarnings(minerAddress: string): Promise<MinerEarning[]> {
    const raw = await rpcCall(
      this.provider,
      'qfc_getMinerEarnings',
      [minerAddress],
    ).catch(() => []);

    if (!Array.isArray(raw)) return [];

    return raw.map((e: any) => ({
      blockHeight: Number(e.blockHeight),
      taskId: e.taskId ?? '',
      reward: e.reward ?? '0x0',
      rewardQfc: this.formatWei(e.reward ?? '0x0'),
      taskType: e.taskType ?? 'unknown',
      modelId: e.modelId ?? '',
      executionTimeMs: Number(e.executionTimeMs ?? 0),
      timestamp: Number(e.timestamp ?? 0),
    }));
  }

  /**
   * Format a notification message for an earning event.
   * Useful for sending to Telegram, Discord, etc.
   */
  formatEarningMessage(earning: MinerEarning): string {
    const config = getNetworkConfig(this.network);
    const explorerUrl = config.explorerUrl;
    const blockUrl = `${explorerUrl}/blocks/${earning.blockHeight}`;
    return [
      `✅ Inference task completed!`,
      `Earned: ${earning.rewardQfc} QFC`,
      `Task: ${earning.taskType}${earning.modelId ? ` (${earning.modelId})` : ''}`,
      `Block: ${earning.blockHeight}`,
      `Time: ${earning.executionTimeMs}ms`,
      blockUrl,
    ].join('\n');
  }

  /**
   * Format a status summary message.
   */
  formatStatusMessage(status: MinerStatus): string {
    const config = getNetworkConfig(this.network);
    const explorerUrl = config.explorerUrl;
    const minerUrl = `${explorerUrl}/miner/${status.address}`;
    return [
      `⛏️ Miner Status`,
      `Total Earned: ${status.totalEarnedQfc} QFC`,
      `Available: ${this.formatWei(status.available)} QFC`,
      `Locked: ${this.formatWei(status.locked)} QFC`,
      `Score: ${status.contributionScore}/100`,
      minerUrl,
    ].join('\n');
  }

  private formatWei(hex: string): string {
    try {
      return ethers.formatEther(BigInt(hex));
    } catch {
      return '0.0';
    }
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig } from './provider.js';

const MULTICALL_ABI = [
  'function aggregate3((address target, bool allowFailure, bytes callData)[] calls) view returns ((bool success, bytes returnData)[])',
];

/**
 * Pre-compiled Multicall3 bytecode (Solidity 0.8.34, evmVersion: paris, optimizer: 200 runs).
 * No constructor args.
 */
const MULTICALL_DEPLOY_BYTECODE = '';

/**
 * Solidity source code for Multicall3.
 */
export const MULTICALL_SOURCE_CODE = `// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Multicall3 {
    struct Call3 {
        address target;
        bool allowFailure;
        bytes callData;
    }

    struct Result {
        bool success;
        bytes returnData;
    }

    function aggregate3(Call3[] calldata calls) external view returns (Result[] memory results) {
        results = new Result[](calls.length);
        for (uint256 i = 0; i < calls.length; i++) {
            (bool success, bytes memory ret) = calls[i].target.staticcall(calls[i].callData);
            if (!calls[i].allowFailure) {
                require(success, "call failed");
            }
            results[i] = Result(success, ret);
        }
    }
}
`;

export interface MulticallCall {
  target: string;
  allowFailure?: boolean;
  callData: string;
}

export interface MulticallResult {
  success: boolean;
  returnData: string;
}

export interface MulticallDeployResult {
  multicallAddress: string;
  txHash: string;
  explorerUrl: string;
}

/**
 * QFCMulticall — Batch multiple view/read calls into a single RPC request.
 */
export class QFCMulticall {
  private provider: ethers.JsonRpcProvider;
  private networkConfig;

  constructor(network: NetworkName = 'testnet') {
    this.networkConfig = getNetworkConfig(network);
    this.provider = createProvider(network);
  }

  private async waitForReceipt(
    txHash: string,
    timeoutMs: number = 120_000,
  ): Promise<{ status: string; contractAddress: string }> {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, 3000));
      const raw = await this.provider.send('eth_getTransactionReceipt', [txHash]);
      if (raw) return raw;
    }
    throw new Error(`Transaction ${txHash} not confirmed after ${timeoutMs / 1000}s`);
  }

  /**
   * Deploy a Multicall3 contract.
   */
  async deploy(signer: ethers.Wallet): Promise<MulticallDeployResult> {
    const connected = signer.connect(this.provider);
    const factory = new ethers.ContractFactory(MULTICALL_ABI, MULTICALL_DEPLOY_BYTECODE, connected);
    const deployTx = await factory.getDeployTransaction();
    deployTx.gasLimit = 800_000n;

    const tx = await connected.sendTransaction(deployTx);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`Multicall3 deployment reverted (tx: ${tx.hash})`);
    }

    // Best-effort verification
    try {
      const verifyUrl = `${this.networkConfig.explorerUrl}/api/contracts/verify`;
      await fetch(verifyUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          address: receipt.contractAddress,
          sourceCode: MULTICALL_SOURCE_CODE,
          compilerVersion: 'v0.8.34+commit.1c8745a5',
          evmVersion: 'paris',
          optimizationRuns: 200,
        }),
      });
    } catch {
      // Explorer unavailable
    }

    return {
      multicallAddress: receipt.contractAddress,
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/contract/${receipt.contractAddress}`,
    };
  }

  /**
   * Execute batch calls via a deployed Multicall3 contract.
   * @param multicallAddress - deployed Multicall3 contract
   * @param calls - array of {target, allowFailure?, callData}
   */
  async call(multicallAddress: string, calls: MulticallCall[]): Promise<MulticallResult[]> {
    const mc = new ethers.Contract(multicallAddress, MULTICALL_ABI, this.provider);
    const formatted = calls.map((c) => ({
      target: c.target,
      allowFailure: c.allowFailure ?? true,
      callData: c.callData,
    }));

    const results = await mc.aggregate3(formatted);
    return results.map((r: { success: boolean; returnData: string }) => ({
      success: r.success,
      returnData: r.returnData,
    }));
  }

  /**
   * Batch query ERC-20 balanceOf for multiple tokens.
   * @param multicallAddress - deployed Multicall3 contract
   * @param tokens - array of token addresses
   * @param owner - wallet address to check
   * @returns array of {token, balance} where balance is raw (not formatted)
   */
  async getTokenBalances(
    multicallAddress: string,
    tokens: string[],
    owner: string,
  ): Promise<{ token: string; balance: string }[]> {
    const iface = new ethers.Interface(['function balanceOf(address) view returns (uint256)']);
    const calls = tokens.map((token) => ({
      target: token,
      allowFailure: true,
      callData: iface.encodeFunctionData('balanceOf', [owner]),
    }));

    const results = await this.call(multicallAddress, calls);
    return results.map((r, i) => ({
      token: tokens[i],
      balance: r.success ? BigInt(r.returnData).toString() : '0',
    }));
  }

  /**
   * Batch query pool reserves for multiple AMM pools.
   * @param multicallAddress - deployed Multicall3 contract
   * @param pools - array of pool addresses
   */
  async getPoolReserves(
    multicallAddress: string,
    pools: string[],
  ): Promise<{ pool: string; reserveA: string; reserveB: string }[]> {
    const iface = new ethers.Interface(['function getReserves() view returns (uint256, uint256)']);
    const calls = pools.map((pool) => ({
      target: pool,
      allowFailure: true,
      callData: iface.encodeFunctionData('getReserves'),
    }));

    const results = await this.call(multicallAddress, calls);
    return results.map((r, i) => {
      if (r.success && r.returnData !== '0x') {
        const decoded = iface.decodeFunctionResult('getReserves', r.returnData);
        return { pool: pools[i], reserveA: decoded[0].toString(), reserveB: decoded[1].toString() };
      }
      return { pool: pools[i], reserveA: '0', reserveB: '0' };
    });
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, rpcCall } from './provider.js';

export interface NodeInfo {
  version: string;
  chainId: number;
  peerCount: number;
  isValidator: boolean;
  syncing: boolean;
}

/**
 * QFCNetwork — node and network status queries.
 */
export class QFCNetwork {
  private provider: ethers.JsonRpcProvider;

  constructor(network: NetworkName = 'testnet') {
    this.provider = createProvider(network);
  }

  /** Get node info via qfc_nodeInfo */
  async getNodeInfo(): Promise<NodeInfo> {
    const info = await rpcCall(this.provider, 'qfc_nodeInfo', []);
    return {
      version: info.version,
      chainId: Number(info.chainId),
      peerCount: Number(info.peerCount),
      isValidator: Boolean(info.isValidator),
      syncing: Boolean(info.syncing),
    };
  }

  /** Get network state (e.g. "normal", "congested") */
  async getNetworkState(): Promise<string> {
    return rpcCall(this.provider, 'qfc_getNetworkState', []);
  }

  /** Get chain ID */
  async getChainId(): Promise<number> {
    const hex = await rpcCall(this.provider, 'eth_chainId', []);
    return Number(hex);
  }

  /** Get latest block number */
  async getBlockNumber(): Promise<number> {
    const hex = await rpcCall(this.provider, 'eth_blockNumber', []);
    return Number(hex);
  }

  /** Get current gas price in Gwei */
  async getGasPrice(): Promise<string> {
    const hex = await rpcCall(this.provider, 'eth_gasPrice', []);
    return ethers.formatUnits(BigInt(hex), 'gwei');
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig } from './provider.js';

const ERC721_ABI = [
  'function name() view returns (string)',
  'function symbol() view returns (string)',
  'function owner() view returns (address)',
  'function totalSupply() view returns (uint256)',
  'function tokenURI(uint256 tokenId) view returns (string)',
  'function ownerOf(uint256 tokenId) view returns (address)',
  'function balanceOf(address owner) view returns (uint256)',
  'function transferFrom(address from, address to, uint256 tokenId)',
  'function approve(address to, uint256 tokenId)',
  'function mint(address to, string uri)',
];

const ERC721_DEPLOY_ABI = [
  'constructor(string name, string symbol)',
  ...ERC721_ABI,
  'event Transfer(address indexed from, address indexed to, uint256 indexed tokenId)',
  'event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId)',
];

/**
 * Solidity source code for the pre-compiled ERC-721 NFT contract.
 * Compile settings: Solidity 0.8.34, evmVersion: paris, optimizer: 200 runs.
 */
export const ERC721_SOURCE_CODE = `// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract SimpleNFT {
    string public name;
    string public symbol;
    address public owner;
    uint256 public totalSupply;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(uint256 => string) private _tokenURIs;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
        owner = msg.sender;
    }

    function mint(address to, string memory uri) external onlyOwner {
        uint256 tokenId = totalSupply;
        totalSupply++;
        _owners[tokenId] = to;
        _balances[to]++;
        _tokenURIs[tokenId] = uri;
        emit Transfer(address(0), to, tokenId);
    }

    function tokenURI(uint256 tokenId) external view returns (string memory) {
        require(_owners[tokenId] != address(0), "nonexistent token");
        return _tokenURIs[tokenId];
    }

    function ownerOf(uint256 tokenId) external view returns (address) {
        address tokenOwner = _owners[tokenId];
        require(tokenOwner != address(0), "nonexistent token");
        return tokenOwner;
    }

    function balanceOf(address _owner) external view returns (uint256) {
        require(_owner != address(0), "zero address");
        return _balances[_owner];
    }

    function approve(address to, uint256 tokenId) external {
        address tokenOwner = _owners[tokenId];
        require(msg.sender == tokenOwner, "not token owner");
        _tokenApprovals[tokenId] = to;
        emit Approval(tokenOwner, to, tokenId);
    }

    function transferFrom(address from, address to, uint256 tokenId) external {
        address tokenOwner = _owners[tokenId];
        require(tokenOwner == from, "not owner");
        require(
            msg.sender == tokenOwner || _tokenApprovals[tokenId] == msg.sender,
            "not authorized"
        );
        _tokenApprovals[tokenId] = address(0);
        _balances[from]--;
        _balances[to]++;
        _owners[tokenId] = to;
        emit Transfer(from, to, tokenId);
    }
}
`;

/**
 * Pre-compiled ERC-721 bytecode (Solidity 0.8.34, evmVersion: paris, optimizer: 200 runs).
 * Constructor: (string name, string symbol)
 */
const ERC721_DEPLOY_BYTECODE = '';

export interface NFTDeployResult {
  contractAddress: string;
  txHash: string;
  explorerUrl: string;
  name: string;
  symbol: string;
  verified?: boolean;
}

export interface NFTMintResult {
  txHash: string;
  tokenId: string;
  explorerUrl: string;
}

export interface NFTInfo {
  contractAddress: string;
  name: string;
  symbol: string;
  totalSupply: string;
}

/**
 * QFCNFT — ERC-721 NFT operations on QFC.
 */
export class QFCNFT {
  private provider: ethers.JsonRpcProvider;
  private networkConfig;

  constructor(network: NetworkName = 'testnet') {
    this.networkConfig = getNetworkConfig(network);
    this.provider = createProvider(network);
  }

  /** Poll for transaction receipt via raw RPC (avoids ethers.js log-parsing issues on QFC) */
  private async waitForReceipt(
    txHash: string,
    timeoutMs: number = 120_000,
  ): Promise<{ status: string; contractAddress: string; blockNumber: string; gasUsed: string }> {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, 3000));
      const raw = await this.provider.send('eth_getTransactionReceipt', [txHash]);
      if (raw) return raw;
    }
    throw new Error(`Transaction ${txHash} not confirmed after ${timeoutMs / 1000}s`);
  }

  /**
   * Deploy a new ERC-721 NFT contract on QFC.
   * Uses a pre-compiled contract (Solidity 0.8.34, Paris EVM, optimizer 200 runs).
   *
   * @param name - collection name (e.g. "My NFT Collection")
   * @param symbol - collection symbol (e.g. "MNFT")
   * @param signer - wallet to deploy from (pays gas, becomes owner)
   */
  async deploy(
    name: string,
    symbol: string,
    signer: ethers.Wallet,
  ): Promise<NFTDeployResult> {
    const connected = signer.connect(this.provider);
    const factory = new ethers.ContractFactory(ERC721_DEPLOY_ABI, ERC721_DEPLOY_BYTECODE, connected);

    const deployTx = await factory.getDeployTransaction(name, symbol);
    deployTx.gasLimit = 1_500_000n;

    const tx = await connected.sendTransaction(deployTx);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`Deploy transaction reverted (tx: ${tx.hash})`);
    }

    const result: NFTDeployResult = {
      contractAddress: receipt.contractAddress,
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/contract/${receipt.contractAddress}`,
      name,
      symbol,
    };

    // Auto-verify on explorer (best-effort)
    try {
      const abiCoder = ethers.AbiCoder.defaultAbiCoder();
      const constructorArgs = abiCoder.encode(
        ['string', 'string'],
        [name, symbol],
      ).slice(2); // remove 0x prefix

      const verifyResponse = await fetch(
        `${this.networkConfig.explorerUrl}/api/contracts/verify`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            address: receipt.contractAddress,
            sourceCode: ERC721_SOURCE_CODE,
            compilerVersion: 'v0.8.34',
            evmVersion: 'paris',
            optimizationRuns: 200,
            constructorArgs,
          }),
        },
      );
      const verifyData = await verifyResponse.json();
      result.verified = verifyData.ok && verifyData.data?.verified;
    } catch {
      result.verified = false;
    }

    return result;
  }

  /**
   * Mint a new NFT to the specified address.
   * @param contractAddress - NFT contract address
   * @param to - recipient address
   * @param uri - token metadata URI
   * @param signer - contract owner wallet
   */
  async mint(
    contractAddress: string,
    to: string,
    uri: string,
    signer: ethers.Wallet,
  ): Promise<NFTMintResult> {
    const connected = signer.connect(this.provider);
    const contract = new ethers.Contract(contractAddress, ERC721_ABI, connected);

    // Get current totalSupply before minting (this will be the new tokenId)
    const totalSupplyBefore = await contract.totalSupply();
    const tokenId = totalSupplyBefore.toString();

    const tx = await contract.mint(to, uri);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`Mint transaction reverted (tx: ${tx.hash})`);
    }

    return {
      txHash: tx.hash,
      tokenId,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${tx.hash}`,
    };
  }

  /**
   * Query the owner of a specific NFT token.
   * @param contractAddress - NFT contract address
   * @param tokenId - token ID to query
   */
  async ownerOf(contractAddress: string, tokenId: string): Promise<string> {
    const contract = new ethers.Contract(contractAddress, ERC721_ABI, this.provider);
    return contract.ownerOf(tokenId);
  }

  /**
   * Query the metadata URI for a specific NFT token.
   * @param contractAddress - NFT contract address
   * @param tokenId - token ID to query
   */
  async getTokenURI(contractAddress: string, tokenId: string): Promise<string> {
    const contract = new ethers.Contract(contractAddress, ERC721_ABI, this.provider);
    return contract.tokenURI(tokenId);
  }

  /**
   * Query the number of NFTs owned by an address.
   * @param contractAddress - NFT contract address
   * @param owner - address to query
   */
  async balanceOf(contractAddress: string, owner: string): Promise<string> {
    const contract = new ethers.Contract(contractAddress, ERC721_ABI, this.provider);
    const balance = await contract.balanceOf(owner);
    return balance.toString();
  }

  /**
   * Transfer an NFT from one address to another.
   * @param contractAddress - NFT contract address
   * @param from - current owner address
   * @param to - recipient address
   * @param tokenId - token ID to transfer
   * @param signer - wallet to sign the transaction (must be owner or approved)
   */
  async transfer(
    contractAddress: string,
    from: string,
    to: string,
    tokenId: string,
    signer: ethers.Wallet,
  ): Promise<{ txHash: string; explorerUrl: string }> {
    const connected = signer.connect(this.provider);
    const contract = new ethers.Contract(contractAddress, ERC721_ABI, connected);
    const tx = await contract.transferFrom(from, to, tokenId);
    const receipt = await this.waitForReceipt(tx.hash);

    if (receipt.status !== '0x1') {
      throw new Error(`Transfer transaction reverted (tx: ${tx.hash})`);
    }

    return {
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${tx.hash}`,
    };
  }
}

import { ethers } from 'ethers';
import networks from '../config/qfc-networks.json' with { type: 'json' };

export type NetworkName = 'testnet' | 'mainnet';

export interface NetworkConfig {
  name: string;
  chainId: number;
  rpcUrl: string;
  explorerUrl: string;
  faucetUrl?: string;
  symbol: string;
  decimals: number;
}

/** Get the config for a named network */
export function getNetworkConfig(network: NetworkName): NetworkConfig {
  return networks[network];
}

/** Create a JsonRpcProvider for the given network */
export function createProvider(network: NetworkName): ethers.JsonRpcProvider {
  const config = getNetworkConfig(network);
  return new ethers.JsonRpcProvider(config.rpcUrl, config.chainId);
}

/** Send a custom JSON-RPC method */
export async function rpcCall(
  provider: ethers.JsonRpcProvider,
  method: string,
  params: any[],
): Promise<any> {
  return provider.send(method, params);
}

interface TransactionCheck {
  to: string;
  amount: number;
  isContractCall?: boolean;
}

interface CheckResult {
  approved: boolean;
  requiresConfirmation: boolean;
  warnings: string[];
}

interface SecurityConfig {
  dailyLimit: number;
  autoApproveBelow: number;
  requireConfirmAlways: boolean;
}

const DEFAULT_CONFIG: SecurityConfig = {
  dailyLimit: 1000,
  autoApproveBelow: 10,
  requireConfirmAlways: false,
};

/**
 * SecurityPolicy — pre-transaction safety checks for wallet operations.
 */
export class SecurityPolicy {
  private config: SecurityConfig;
  private dailySpent: number = 0;
  private knownAddresses: Set<string> = new Set();

  constructor(config?: Partial<SecurityConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /** Mark an address as known/trusted */
  addKnownAddress(address: string): void {
    this.knownAddresses.add(address.toLowerCase());
  }

  /** Run pre-transaction checks */
  preTransactionCheck(tx: TransactionCheck): CheckResult {
    // Rule 1: Validate address format first — reject before any other processing
    if (tx.to.includes(' ') || tx.to.length !== 42 || !tx.to.startsWith('0x')) {
      return {
        approved: false,
        requiresConfirmation: false,
        warnings: ['Invalid address format — possible injection attempt'],
      };
    }

    const warnings: string[] = [];
    let requiresConfirmation = this.config.requireConfirmAlways;

    // Rule 2: Large transaction (>100 QFC)
    if (tx.amount > 100) {
      warnings.push(`Large transaction: ${tx.amount} QFC exceeds 100 QFC threshold`);
      requiresConfirmation = true;
    }

    // Rule 3: New/unknown address
    if (!this.knownAddresses.has(tx.to.toLowerCase())) {
      warnings.push(`New recipient address: ${tx.to} (not previously used)`);
      if (tx.amount > this.config.autoApproveBelow) {
        requiresConfirmation = true;
      }
    }

    // Rule 4: Contract call
    if (tx.isContractCall) {
      warnings.push('Transaction involves a contract call');
      requiresConfirmation = true;
    }

    // Rule 5: Daily spending limit
    if (this.dailySpent + tx.amount > this.config.dailyLimit) {
      warnings.push(
        `Daily limit: spending ${this.dailySpent + tx.amount} QFC exceeds ${this.config.dailyLimit} QFC daily limit`,
      );
      requiresConfirmation = true;
    }

    // Auto-approve small transactions to known addresses
    const approved =
      !requiresConfirmation &&
      tx.amount <= this.config.autoApproveBelow &&
      this.knownAddresses.has(tx.to.toLowerCase());

    return { approved, requiresConfirmation, warnings };
  }

  /** Record a completed transaction toward the daily limit */
  recordTransaction(amount: number): void {
    this.dailySpent += amount;
  }

  /** Reset daily spending counter */
  resetDailySpent(): void {
    this.dailySpent = 0;
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, rpcCall } from './provider.js';

export interface ValidatorInfo {
  address: string;
  stake: string;
  contributionScore: number;
  isActive: boolean;
  computeMode: string;
}

export interface ScoreBreakdown {
  address: string;
  totalScore: number;
  stake: string;
  dimensions: {
    stake: number;
    compute: number;
    uptime: number;
    accuracy: number;
    network: number;
    storage: number;
    reputation: number;
  };
  metrics: {
    uptimePercent: string;
    accuracyPercent: string;
    blocksProduced: number;
    providesCompute: boolean;
  };
}

/**
 * QFCStaking — validator and staking information.
 */
export class QFCStaking {
  private provider: ethers.JsonRpcProvider;

  constructor(network: NetworkName = 'testnet') {
    this.provider = createProvider(network);
  }

  /** Get all validators */
  async getValidators(): Promise<ValidatorInfo[]> {
    const raw: any[] = await rpcCall(this.provider, 'qfc_getValidators', []);
    return raw.map((v) => ({
      address: v.address,
      stake: ethers.formatEther(BigInt(v.stake)),
      contributionScore: Number(v.contributionScore),
      isActive: Boolean(v.isActive),
      computeMode: v.computeMode ?? 'none',
    }));
  }

  /** Get stake amount for an address (returns QFC) */
  async getStake(address: string): Promise<string> {
    const hex = await rpcCall(this.provider, 'qfc_getStake', [address]);
    return ethers.formatEther(BigInt(hex));
  }

  /** Get contribution score (0-10000) */
  async getContributionScore(address: string): Promise<number> {
    const raw = await rpcCall(this.provider, 'qfc_getContributionScore', [address]);
    return Number(raw);
  }

  /** Get detailed score breakdown */
  async getScoreBreakdown(address: string): Promise<ScoreBreakdown> {
    const raw = await rpcCall(this.provider, 'qfc_getValidatorScoreBreakdown', [address]);
    if (!raw || !raw.address) {
      throw new Error(`No score breakdown found for ${address}`);
    }
    const metrics = raw.metrics ?? {};
    return {
      address: raw.address,
      totalScore: Number(raw.totalScore),
      stake: ethers.formatEther(BigInt(raw.stake ?? '0x0')),
      dimensions: {
        stake: Number(raw.stakeScore ?? 0),
        compute: Number(raw.computeScore ?? 0),
        uptime: Number(raw.uptimeScore ?? 0),
        accuracy: Number(raw.accuracyScore ?? 0),
        network: Number(raw.networkScore ?? 0),
        storage: Number(raw.storageScore ?? 0),
        reputation: Number(raw.reputationScore ?? 0),
      },
      metrics: {
        uptimePercent: metrics.uptimePercent ?? '0',
        accuracyPercent: metrics.accuracyPercent ?? '0',
        blocksProduced: Number(metrics.blocksProduced ?? 0),
        providesCompute: Boolean(metrics.providesCompute),
      },
    };
  }
}

import { ethers } from 'ethers';
import { NetworkName, createProvider, getNetworkConfig } from './provider.js';
import { QFCKeystore, type WalletMeta } from './keystore.js';
import type { BatchTransferItem, BatchTransferResult } from './token.js';

interface WalletCreationResult {
  address: string;
  mnemonic: string;
  privateKey: string;
}

interface BalanceResult {
  qfc: string;
  wei: string;
}

interface SendResult {
  txHash: string;
  explorerUrl: string;
}

/**
 * QFC Wallet — manages wallet operations on the QFC blockchain.
 */
export class QFCWallet {
  private provider: ethers.JsonRpcProvider;
  private wallet: ethers.Wallet | null = null;
  private network: NetworkName;
  private networkConfig;

  constructor(network: NetworkName = 'testnet') {
    this.network = network;
    this.networkConfig = getNetworkConfig(network);
    this.provider = createProvider(network);
  }

  /** Create a new random wallet */
  createWallet(): WalletCreationResult {
    const hdWallet = ethers.Wallet.createRandom();
    this.wallet = new ethers.Wallet(hdWallet.privateKey, this.provider);
    return {
      address: hdWallet.address,
      mnemonic: hdWallet.mnemonic!.phrase,
      privateKey: hdWallet.privateKey,
    };
  }

  /** Import an existing wallet from private key */
  importWallet(privateKey: string): string {
    this.wallet = new ethers.Wallet(privateKey, this.provider);
    return this.wallet.address;
  }

  /** Get balance for an address (defaults to current wallet) */
  async getBalance(address?: string): Promise<BalanceResult> {
    const target = address ?? this.requireWallet().address;
    const balance = await this.provider.getBalance(target);
    return {
      qfc: ethers.formatEther(balance),
      wei: balance.toString(),
    };
  }

  /** Send QFC to an address */
  async sendQFC(
    to: string,
    amount: string,
    opts?: { gasLimit?: number },
  ): Promise<SendResult> {
    if (!ethers.isAddress(to)) {
      throw new Error('Invalid address format. Expected 0x + 40 hex characters.');
    }
    const wallet = this.requireWallet();
    const tx = await wallet.sendTransaction({
      to,
      value: ethers.parseEther(amount),
      gasLimit: opts?.gasLimit,
    });
    const receipt = await this.waitForReceipt(tx.hash);
    if (receipt.status !== '0x1') {
      throw new Error(`Transaction reverted (tx: ${tx.hash})`);
    }
    return {
      txHash: tx.hash,
      explorerUrl: `${this.networkConfig.explorerUrl}/txs/${tx.hash}`,
    };
  }

  /** Sign a message with the current wallet */
  async signMessage(message: string): Promise<string> {
    const wallet = this.requireWallet();
    return wallet.signMessage(message);
  }

  /** Get the current wallet address */
  get address(): string | null {
    return this.wallet?.address ?? null;
  }

  /** Save current wallet to encrypted keystore on disk */
  async save(password: string, name?: string): Promise<void> {
    const wallet = this.requireWallet();
    const ks = new QFCKeystore();
    await ks.saveWallet(wallet, password, { name, network: this.network });
  }

  /** Load a wallet from encrypted keystore */
  static async load(
    address: string,
    password: string,
    network: NetworkName = 'testnet',
  ): Promise<QFCWallet> {
    const ks = new QFCKeystore();
    const raw = await ks.loadWallet(address, password);
    const instance = new QFCWallet(network);
    instance.importWallet(raw.privateKey);
    return instance;
  }

  /** List all saved wallets (no password needed) */
  static listSaved(): WalletMeta[] {
    const ks = new QFCKeystore();
    return ks.listWallets();
  }

  /** Poll for transaction receipt via raw RPC (avoids ethers.js log-parsing issues on QFC) */
  private async waitForReceipt(
    txHash: string,
    timeoutMs: number = 120_000,
  ): Promise<{ status: string; blockNumber: string }> {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, 3000));
      const raw = await this.provider.send('eth_getTransactionReceipt', [txHash]);
      if (raw) return raw;
    }
    throw new Error(`Transaction ${txHash} not confirmed after ${timeoutMs / 1000}s`);
  }

  /**
   * Batch send native QFC to multiple addresses sequentially.
   * @param recipients - array of {to, amount} objects (amount in QFC, e.g. "10")
   * @param signer - wallet to sign the transactions
   */
  async batchSend(
    recipients: BatchTransferItem[],
    signer: ethers.Wallet,
  ): Promise<BatchTransferResult> {
    const connected = signer.connect(this.provider);
    const result: BatchTransferResult = { successful: [], failed: [] };

    for (const recipient of recipients) {
      try {
        if (!ethers.isAddress(recipient.to)) {
          result.failed.push({ to: recipient.to, amount: recipient.amount, error: 'Invalid address format' });
          continue;
        }
        const tx = await connected.sendTransaction({
          to: recipient.to,
          value: ethers.parseEther(recipient.amount),
        });
        const receipt = await this.waitForReceipt(tx.hash);
        if (receipt.status !== '0x1') {
          result.failed.push({ to: recipient.to, amount: recipient.amount, error: 'Transaction reverted' });
        } else {
          result.successful.push({ to: recipient.to, amount: recipient.amount, txHash: tx.hash });
        }
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : String(err);
        result.failed.push({ to: recipient.to, amount: recipient.amount, error: message });
      }
    }

    return result;
  }

  private requireWallet(): ethers.Wallet {
    if (!this.wallet) {
      throw new Error('No wallet loaded. Call createWallet() or importWallet() first.');
    }
    return this.wallet;
  }
}

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { QFCWallet, QFCKeystore } from './dist/index.js';

const TEST_DIR = path.join(os.tmpdir(), 'qfc-keystore-test-' + Date.now());
const PASSWORD = 'test-password-123';

async function run() {
  const ks = new QFCKeystore(TEST_DIR);

  // 1. Create wallet
  const w = new QFCWallet('testnet');
  const { address } = w.createWallet();
  console.log('1. Create wallet →', address);

  // 2. Save encrypted
  await ks.saveWallet(
    (await import('ethers')).ethers.Wallet.createRandom(), // fresh wallet for isolated test
    PASSWORD,
    { name: 'test-wallet', network: 'testnet' },
  );
  // Also test via QFCWallet.save (uses default dir, so use keystore directly)
  const { ethers } = await import('ethers');
  const testWallet = ethers.Wallet.createRandom();
  const savedPath = await ks.saveWallet(testWallet, PASSWORD, {
    name: 'test-wallet',
    network: 'testnet',
  });
  console.log('2. Save encrypted → saved to', savedPath);

  // 3. List wallets
  const list = ks.listWallets();
  console.log(
    '3. List wallets →',
    list.map((m) => ({ address: m.address, name: m.name, network: m.network })),
  );

  // 4. Load wallet
  const loaded = await ks.loadWallet(testWallet.address, PASSWORD);
  const match = loaded.address.toLowerCase() === testWallet.address.toLowerCase();
  console.log('4. Load wallet → address matches:', match);
  if (!match) {
    console.error('   FAIL: expected', testWallet.address, 'got', loaded.address);
    process.exit(1);
  }

  // 5. Export keystore JSON
  const json = ks.getKeystoreJson(testWallet.address);
  console.log('5. Export keystore JSON →', json ? 'OK (' + json.length + ' bytes)' : 'FAIL');

  // 6. Remove wallet
  const removed = ks.removeWallet(testWallet.address);
  const listAfter = ks.listWallets();
  console.log('6. Remove wallet → removed:', removed, '| remaining:', listAfter.length);

  // 7. File permissions
  const metaPath = path.join(TEST_DIR, 'meta.json');
  if (fs.existsSync(metaPath)) {
    const stat = fs.statSync(metaPath);
    const mode = '0' + (stat.mode & 0o777).toString(8);
    console.log('7. File permissions → meta.json:', mode);
  }

  // Cleanup
  fs.rmSync(TEST_DIR, { recursive: true, force: true });
  console.log('\nAll tests passed!');
}

run().catch((err) => {
  console.error('Test failed:', err);
  // Cleanup on error too
  fs.rmSync(TEST_DIR, { recursive: true, force: true });
  process.exit(1);
});

/**
 * Integration test for all QFC OpenClaw modules.
 * Run: node test-modules.mjs
 */

import {
  QFCFaucet,
  QFCChain,
  QFCNetwork,
  QFCStaking,
  QFCEpoch,
} from './dist/index.js';

async function main() {
  console.log('=== QFC OpenClaw Modules Test ===\n');

  // 1. Faucet
  try {
    const faucet = new QFCFaucet('testnet');
    const addr = '0x' + '1'.repeat(40);
    const result = await faucet.requestQFC(addr, '10');
    console.log(`1. Faucet: requested ${result.amount} QFC → txHash: ${result.txHash}`);
  } catch (e) {
    console.log(`1. Faucet: ${e.message}`);
  }

  // 2. Chain
  try {
    const chain = new QFCChain('testnet');
    const blockNum = await chain.getBlockNumber();
    const block = await chain.getBlock('latest');
    console.log(`2. Chain: block #${block.number}, ${block.transactionCount} txs`);
  } catch (e) {
    console.log(`2. Chain: ${e.message}`);
  }

  // 3. Network
  try {
    const net = new QFCNetwork('testnet');
    const info = await net.getNodeInfo();
    const state = await net.getNetworkState();
    console.log(`3. Network: node ${info.version}, ${info.peerCount} peers, ${state}`);
  } catch (e) {
    console.log(`3. Network: ${e.message}`);
  }

  // 4. Staking
  try {
    const staking = new QFCStaking('testnet');
    const validators = await staking.getValidators();
    const totalStake = validators.reduce((sum, v) => sum + parseFloat(v.stake), 0);
    console.log(`4. Staking: ${validators.length} validators, total stake ${totalStake} QFC`);
  } catch (e) {
    console.log(`4. Staking: ${e.message}`);
  }

  // 5. Epoch
  try {
    const epoch = new QFCEpoch('testnet');
    const info = await epoch.getCurrentEpoch();
    const finalized = await epoch.getFinalizedBlock();
    console.log(`5. Epoch: epoch #${info.number}, finalized block #${finalized}`);
  } catch (e) {
    console.log(`5. Epoch: ${e.message}`);
  }

  console.log('\n=== Done ===');
}

main().catch(console.error);
